// Desktop OS – Deel I: Linux – Werkcollege 3
// v = vraag, a = antwoord, o = onderwerp, uitleg = extra uitleg, img/imgAntwoord = afbeelding (map afbeeldingen/)
// wit: true = witte kaart die de cursus voorstelt · extra: true = extra info, niet uit de cursus (turquoise rand)
// oefening: true = blauwe oefenkaart: typ het commando. In a staan commando's na "$ "; regels die met 2 spaties beginnen zijn toetsen of uitvoer.
// De structuur onderaan bepaalt het overzicht rechts.

const kaarten_DOS_linux_wc3 = [
  // ===== sudo en root =====
  { v: "Root-rechten in Linux: sudo (1)", a: "• De administrator heet root. Zijn homefolder is /root, rechtstreeks onder de root van de boom (niet onder /home).\n• Rechtstreeks inloggen als root wordt sterk afgeraden: gebruik sudo ('superuser-do').\n• Leden van de sudoers-groep hebben sudo-rechten: zet sudo voor het commando.\n• adduser test zonder sudo: 'Only root may add a user or group to the system.' Met sudo adduser test werkt het (na je eigen paswoord).\n• Gebruik sudo enkel wanneer strikt noodzakelijk: bij instellingen met impact op het hele systeem of op andere gebruikers, bv. netwerkinstellingen of het paswoord van een andere gebruiker.", o: "sudo en root", wit: true,
    uitleg: "Anders zet je je computer open voor veiligheidsproblemen." },
  { v: "Hoe heet de administrator in Linux, en waar staat zijn homefolder?", a: "root. Zijn homefolder is /root, rechtstreeks onder de root van de boomstructuur (niet onder /home).", o: "sudo en root",
    uitleg: "Veel 'root': de gebruiker root, de root / van het bestandssysteem, en /root als homefolder van root." },
  { v: "Wordt het aangeraden om rechtstreeks in te loggen als root? Wat doe je in de plaats?", a: "Nee, dat wordt sterk afgeraden. In de plaats gebruik je sudo voor het commando dat beheerdersrechten nodig heeft.", o: "sudo en root",
    uitleg: "Zo werk je standaard met beperkte rechten en geef je enkel extra rechten waar nodig: minder risico op fouten en misbruik." },
  { v: "Waar staat sudo voor, en wie mag het gebruiken?", a: "superuser do: voer het commando uit met administratorrechten. Enkel gebruikers die lid zijn van de sudoers-groep.", o: "sudo en root",
    uitleg: "Je zet sudo gewoon vóór het commando, bv. sudo adduser test. Daarna vraagt Linux je eigen paswoord." },
  { v: "Wat gebeurt er als je adduser test uitvoert zonder sudo?", a: "Je krijgt de melding: 'Only root may add a user or group to the system.'", o: "sudo en root",
    uitleg: "Met sudo adduser test werkt het wel (na het ingeven van je paswoord)." },
  { v: "Wanneer gebruik je sudo best? Geef 2 voorbeelden.", a: "Enkel wanneer strikt noodzakelijk: als je een instelling wil aanpassen die impact heeft op het hele systeem of op andere gebruikers. Bv. de netwerkinstellingen aanpassen, of het paswoord van een andere gebruiker veranderen.", o: "sudo en root",
    uitleg: "sudo onnodig gebruiken zet je computer open voor veiligheidsproblemen: een fout of een kwaadaardig script kan dan alles kapotmaken." },
  { v: "Juist of fout? Elke gebruiker kan sudo gebruiken.", a: "FOUT", o: "sudo en root",
    uitleg: "Enkel leden van de sudoers-groep. In de oefening wordt sudo geweigerd aan de gebruiker test, omdat die geen lid is van de sudoers-groep, en zo hoort het ook." },
  { v: "Maak als admin de gebruiker test aan.", a: "$ sudo adduser test", o: "sudo en root", oefening: true },
  { v: "Homefolder van root", a: "/root", o: "sudo en root" },
  { v: "Wie mag sudo gebruiken?", a: "leden van de sudoers-groep", o: "sudo en root" },
  { v: "Wat is de sudoers-groep?", a: "Een groep waarvan elk lid sudo-rechten (administratorrechten) heeft.", o: "sudo en root",
    uitleg: "Op Ubuntu heet die groep gewoon sudo." },
  { v: "Hoe voer je een commando uit met sudo-rechten?", a: "Je zet er gewoon sudo voor.", o: "sudo en root",
    uitleg: "Bv. sudo apt update. Je moet je eigen paswoord ingeven (niet dat van root)." },
  { v: "Volg de vragen en maak een user ‘test’ met als paswoord ‘Student2’, volledige naam ‘testgebruiker’, de rest mag je blanco laten.", a: "$ sudo adduser test\n  paswoord: Student2 (twee keer)\n  Full Name: testgebruiker\n  de rest: Enter", o: "sudo en root", oefening: true,
    uitleg: "adduser stelt de vragen stap voor stap; met Enter laat je een veld leeg." },
  { v: "Wat is een goede richtlijn voor het gebruik van sudo?", a: "Gebruik enkel sudo wanneer je een instelling wil aanpassen die impact heeft op het hele systeem of op andere gebruikers.", o: "sudo en root",
    uitleg: "Netwerkinstellingen en andermans paswoord: systeembrede of andermans zaken." },
  { v: "Welke voorbeelden worden daarvan gegeven?", a: "Aanpassingen van de netwerkinstellingen, of het veranderen van het paswoord van een andere gebruiker.", o: "sudo en root",
    uitleg: "Ook: software installeren (apt) en gebruikers aanmaken." },
  { v: "Wat wordt sterk afgeraden en wat gebruik je in de plaats?", a: "Rechtstreeks inloggen als root · in de plaats gebruik je sudo.", o: "sudo en root" },
  { v: "Waarvoor staat sudo?", a: "superuser-do: doe het met administratorrechten.", o: "sudo en root" },
  { v: "Waarom gebruik je sudo enkel wanneer het strikt noodzakelijk is?", a: "Anders zet je je computer open voor veiligheidsproblemen.", o: "sudo en root" },
  { v: "Hoe heet de administrator in Linux?", a: "root", o: "sudo en root", examen: true,
    uitleg: "root is de superuser in Linux: de gebruiker met alle rechten op het systeem. Het UID van root is 0.\nIn Windows heet het equivalent Administrator." },
  { v: "Waar of niet waar: de homefolder van root is /home/root.", a: "Niet waar. Het is /root.", o: "sudo en root", examen: true,
    uitleg: "De homedirectory van root is /root, rechtstreeks onder de root /. Gewone gebruikers hebben hun homedirectory onder /home.\nNiet te verwarren: / is de root van het bestandssysteem, /root is de map van de gebruiker root." },
  { v: "Waarvoor staat de afkorting sudo?", a: "Superuser do: doe het met administratorrechten.", o: "sudo en root", examen: true,
    uitleg: "sudo voert één commando uit met de rechten van root, bv. sudo apt update. Je geeft je eigen wachtwoord in, niet dat van root.\nNa een tijdje (standaard 15 minuten) vraagt sudo opnieuw het wachtwoord." },
  { v: "Welke gebruikers kunnen sudo gebruiken?", a: "Leden van de sudoers-groep.", o: "sudo en root", examen: true,
    uitleg: "Enkel gebruikers die in de sudoers-lijst staan, meestal via de groep sudo (Ubuntu, Debian) of wheel (Red Hat), mogen sudo gebruiken. Die lijst staat in /etc/sudoers.\nAndere gebruikers krijgen: is not in the sudoers file." },
  { v: "Waarom log je best niet rechtstreeks in als root?", a: "Veiligheid: je gebruikt beter sudo enkel waar nodig.", o: "sudo en root", examen: true,
    uitleg: "Als root kan elk commando, ook een typfout, het hele systeem beschadigen. Met sudo krijg je de extra rechten enkel voor dat ene commando, waar het echt nodig is.\nsudo houdt ook bij wie welk commando met adminrechten uitgevoerd heeft (in /var/log/auth.log)." },
  { v: "Wanneer gebruik je sudo volgens de richtlijn?", a: "Enkel bij instellingen met impact op het hele systeem of op andere gebruikers (bv. netwerkinstellingen, paswoord van een andere gebruiker).", o: "sudo en root", examen: true,
    uitleg: "sudo gebruik je enkel als een commando impact heeft op het hele systeem of op andere gebruikers, bv.:\nsoftware installeren (apt)\nnetwerkinstellingen wijzigen\ngebruikers aanmaken of het paswoord van een andere gebruiker wijzigen\nVoor je eigen bestanden in je homedirectory heb je geen sudo nodig." },
  { v: "Je typt adduser test en krijgt \"Only root may add a user or group to the system.\" Wat moet je typen?", a: "sudo adduser test", o: "sudo en root", examen: true,
    uitleg: "Gebruikers aanmaken heeft impact op het hele systeem, dus het mag enkel root. Met sudo ervoor voer je het commando uit met de rechten van root.\nJe moet daarvoor zelf in de sudoers-groep zitten." },
  { v: "Waarom kan gebruiker test geen nieuwe gebruiker aanmaken met sudo?", a: "test is geen lid van de sudoers-groep.", o: "sudo en root", examen: true,
    uitleg: "Een nieuwe gebruiker zit standaard niet in de groep sudo. Probeert test sudo te gebruiken, dan krijgt hij: test is not in the sudoers file.\nOplossing (als iemand met sudo-rechten): sudo usermod -aG sudo test." },
  // ===== /etc/passwd en /etc/group =====
  { v: "Gebruikers: /etc/passwd en /etc/group (2)", a: "• /etc/passwd: alle info over de gebruikers, één lijn per gebruiker, velden gescheiden door ':'.\n• Velden van links naar rechts: login · password (een x) · user-ID · group-ID · informatie · home-dir · shell.\n• Good to know: met cut haal je info uit dit bestand, bv. een lijst van alle gebruikte shells, weggeschreven naar een ander bestand.\n• /etc/group: alle groepen met hun ID en hun leden.\n• id toont in welke groepen je zelf zit.\n\nOpdracht: zoek welke gebruikers in dezelfde groep zitten als jij.", o: "/etc/passwd en /etc/group", wit: true },
  { v: "In welk bestand staat de informatie over de gebruikers, en hoe is het opgebouwd?", a: "In /etc/passwd. Elke gebruiker staat op een eigen regel; de onderdelen worden gescheiden door een dubbele punt (:).", o: "/etc/passwd en /etc/group",
    uitleg: "Bekijken met cat /etc/passwd of less /etc/passwd. Een gebruiker zoeken: grep test2 /etc/passwd." },
  { v: "Welke 7 velden staan er per gebruiker in /etc/passwd (van links naar rechts)?", a: "1. login\n2. password (weergegeven door een x)\n3. user-ID (UID)\n4. group-ID (GID)\n5. informatie\n6. home-dir\n7. shell", o: "/etc/passwd en /etc/group",
    uitleg: "Voorbeeld: testuser:x:1007:1007:test,,,:/home/testuser:/bin/bash. De x betekent dat het echte (versleutelde) paswoord in /etc/shadow staat. Root heeft UID 0; gewone gebruikers beginnen meestal bij 1000." },
  { v: "Lees deze regel uit /etc/passwd: student:x:1000:1000:Student,,,:/home/student:/bin/bash", a: "login = student\npaswoord = x (staat in /etc/shadow)\nUID = 1000\nGID = 1000\ninformatie = Student\nhomedirectory = /home/student\nshell = /bin/bash", o: "/etc/passwd en /etc/group",
    uitleg: "Zo kan je per gebruiker zien waar zijn home is en welke shell start bij het inloggen." },
  { v: "Wat is een UID en een GID?", a: "UID (user-ID) = het nummer waarmee een gebruiker gekend is in het systeem. GID (group-ID) = het nummer waarmee een groep gekend is.", o: "/etc/passwd en /etc/group",
    uitleg: "Linux werkt intern met de nummers, niet met de namen. Het GID in /etc/passwd is de hoofdgroep, op te zoeken in /etc/group." },
  { v: "Waar vind je alle groepen met hun ID en leden, en hoe zie je in welke groepen jij zit?", a: "In /etc/group. Je eigen groepen zie je met het commando id.", o: "/etc/passwd en /etc/group",
    uitleg: "Wie zit in dezelfde groep als jij? Bv. grep student /etc/group. In het oplossingendocument: cut /etc/passwd -d: -f 1,4 | grep 1000 toont de gebruikers met groep 1000." },
  { v: "Bestand met alle gebruikers", a: "/etc/passwd", o: "/etc/passwd en /etc/group" },
  { v: "Schrijf de lijst van alle gebruikte shells uit /etc/passwd weg naar shells.txt.", a: "$ cut -d: -f7 /etc/passwd > shells.txt", o: "/etc/passwd en /etc/group", oefening: true },
  { v: "Toon in welke groepen je zit.", a: "$ id", o: "/etc/passwd en /etc/group", oefening: true },
  { v: "Waar vind je alle informatie i.v.m. de gebruikers op het systeem?", a: "In het bestand /etc/passwd.", o: "/etc/passwd en /etc/group",
    uitleg: "Iedereen mag /etc/passwd lezen (cat /etc/passwd)." },
  { v: "Welk commando is handig om informatie uit /etc/passwd te halen?", a: "Het commando cut.", o: "/etc/passwd en /etc/group",
    uitleg: "cut -d: -f1 /etc/passwd toont de loginnamen (zie werkcollege 2)." },
  { v: "Good to know: Probeer eens enkel een lijst te tonen van alle gebruikte shells door de gebruikers, en dit dan in een ander bestand weg te schrijven.", a: "$ cut -d: -f7 /etc/passwd > shells.txt", o: "/etc/passwd en /etc/group", extra: true, nietTeKennen: true,
    uitleg: "De shell is het 7de (laatste) veld in /etc/passwd; > schrijft de uitvoer naar een bestand. Met sort -u zie je elke shell maar één keer: cut -d: -f7 /etc/passwd | sort -u > shells.txt" },
  { v: "Zoek uit welke gebruikers er allemaal in de groep zitten waar je zelf ook lid van bent.", a: "$ id\n$ grep student /etc/group", o: "/etc/passwd en /etc/group", oefening: true,
    uitleg: "Met id zie je je groepen; in /etc/group staan de leden achteraan elke regel, bv. sudo:x:27:student (groepsnaam, x, group-ID, leden)." },
  { v: "Bekijk de lijn van je eigen gebruiker in /etc/passwd.", a: "$ grep student /etc/passwd", o: "/etc/passwd en /etc/group", oefening: true,
    uitleg: "Vervang student door je eigen username." },
  { v: "In welk bestand vind je alle groepen met hun ID en hun leden?", a: "/etc/group", o: "/etc/passwd en /etc/group" },
  { v: "useradd met een groep (-g)", a: "sudo useradd -m -g testgroep testuser3: testuser3 zit dan meteen in testgroep.", o: "/etc/passwd en /etc/group", extra: true,
    uitleg: "Uit je samenvatting, niet uit de cursus. De optie -g geeft de hoofdgroep mee; de groep moet al bestaan." },
  { v: "In welk bestand staat alle informatie over de gebruikers?", a: "/etc/passwd", o: "/etc/passwd en /etc/group", examen: true,
    uitleg: "/etc/passwd bevat één regel per gebruiker: login, x, UID, GID, informatie, homedirectory en shell.\nIedereen mag het lezen. De echte versleutelde wachtwoorden staan in /etc/shadow, dat enkel root mag lezen." },
  { v: "Welk teken scheidt de velden in /etc/passwd?", a: ": (dubbelpunt)", o: "/etc/passwd en /etc/group", examen: true,
    uitleg: "De velden in /etc/passwd zijn gescheiden door een dubbelpunt.\nDaarom gebruik je bij cut de optie -d: om er een kolom uit te halen, bv. cut -d: -f1 /etc/passwd." },
  { v: "Geef de 7 velden van /etc/passwd in volgorde.", a: "login, password (x), user-ID (UID), group-ID (GID), informatie, home-dir, shell.", o: "/etc/passwd en /etc/group", examen: true,
    uitleg: "1 login: de gebruikersnaam\n2 password: een x, het echte wachtwoord staat in /etc/shadow\n3 UID: het nummer van de gebruiker\n4 GID: het nummer van de primaire groep\n5 informatie: bv. de volledige naam\n6 home-dir: de homedirectory\n7 shell: de shell die start bij het inloggen" },
  { v: "Gegeven:\ntest:x:1001:1001:test,,,:/home/test:/bin/bash\n\nWaarvoor staat de eerste \"test\"?\n\n1: shell\n2: paswoord\n3: UID\n4: GID\n5: homefolder\n6: rechten\n7: naam van de gebruiker", a: "7: de naam van de gebruiker (login).", o: "/etc/passwd en /etc/group", examen: true,
    uitleg: "Het eerste veld van een regel in /etc/passwd is altijd de login: de naam van de gebruiker.\nHier heet de gebruiker test. De velden zijn gescheiden door een dubbelpunt." },
  { v: "Gegeven:\ntest:x:1001:1001:test,,,:/home/test:/bin/bash\n\nWaarvoor staat de x?", a: "Het paswoord (weergegeven door een x).", o: "/etc/passwd en /etc/group", examen: true,
    uitleg: "Het tweede veld is het paswoord. Er staat enkel een x: het versleutelde wachtwoord staat in /etc/shadow, dat enkel root mag lezen.\nZo kan iedereen /etc/passwd lezen zonder de wachtwoorden te zien." },
  { v: "Gegeven:\ntest:x:1001:1001:test,,,:/home/test:/bin/bash\n\nWat is het eerste 1001 en wat het tweede 1001?", a: "Eerste: UID (user-ID). Tweede: GID (group-ID).", o: "/etc/passwd en /etc/group", examen: true,
    uitleg: "Veld 3 = UID (user-ID): het nummer van de gebruiker.\nVeld 4 = GID (group-ID): het nummer van zijn primaire groep.\nBij adduser krijgt elke gebruiker een eigen groep met dezelfde naam en hetzelfde nummer, daarom zijn beide hier 1001.\nGewone gebruikers beginnen in Ubuntu bij 1000; root heeft 0." },
  { v: "Gegeven:\ntest:x:1001:1001:test,,,:/home/test:/bin/bash\n\nWat is /home/test en wat /bin/bash?", a: "/home/test: de homedirectory. /bin/bash: de shell.", o: "/etc/passwd en /etc/group", examen: true,
    uitleg: "Veld 6 = de homedirectory: /home/test.\nVeld 7 = de shell die start als de gebruiker inlogt: /bin/bash.\nStaat er /bin/false of /usr/sbin/nologin, dan kan de gebruiker niet inloggen in een shell." },
  { v: "Gegeven:\ntest:x:1001:1001:test,,,:/home/test:/bin/bash\n\nWat is \"test,,,\"?", a: "Het informatieveld (bv. volledige naam).", o: "/etc/passwd en /etc/group", examen: true,
    uitleg: "Veld 5 is het informatieveld (GECOS). adduser vraagt daarvoor: volledige naam, kamernummer, telefoon werk, telefoon thuis, gescheiden door komma's.\nHier is enkel de naam ingevuld (test), de andere velden zijn leeg: daarom de drie komma's." },
  { v: "In welk bestand vind je alle groepen met hun ID en leden?", a: "/etc/group", o: "/etc/passwd en /etc/group", examen: true,
    uitleg: "/etc/group bevat één regel per groep: groepsnaam:x:GID:leden\nVoorbeeld: sudo:x:27:student\nDe leden staan achteraan, gescheiden door komma's." },
  { v: "Met welk commando zie je in welke groepen je zelf zit?", a: "id", o: "/etc/passwd en /etc/group", examen: true,
    uitleg: "id toont je UID, je GID (primaire groep) en alle groepen waarin je zit, met hun nummer.\nVoorbeeld: uid=1000(student) gid=1000(student) groups=1000(student),27(sudo)\ngroups toont enkel de namen van de groepen." },
  // ===== Gebruikers beheren =====
  { v: "Gebruikers beheren: adduser (3)", a: "Een soort wizard die de belangrijkste informatie vraagt.", o: "Gebruikers beheren", wit: true },
  { v: "Gebruikers beheren: useradd (3)", a: "Veel meer parameters, bv. de shell en de homedirectory. Handig om users in bulk aan te maken via een bash-script.", o: "Gebruikers beheren", wit: true },
  { v: "Gebruikers beheren: usermod (3)", a: "Instellingen van een gebruiker wijzigen ('mod' van modify).\n\nOpdracht: maak /test en een gebruiker test2 met home /test/test2 en shell /bin/false (mag niet aanloggen). Wijzig daarna zijn home naar /home/test2 en zijn shell naar /bin/bash. Verifieer telkens in /etc/passwd.", o: "Gebruikers beheren", wit: true },
  { v: "Paswoorden: passwd (3)", a: "• passwd zonder gebruikersnaam: het paswoord wijzigen van de gebruiker waarmee je aangelogd bent.\n• passwd met een gebruikersnaam: het paswoord van die gebruiker wijzigen. Dat raakt een andere gebruiker, dus sudo is nodig.\n\nOpdracht: wijzig het paswoord van de gebruiker test.", o: "Gebruikers beheren", wit: true },
  { v: "Wat is het verschil tussen adduser en useradd?", a: "adduser werkt als een wizard die de belangrijkste informatie vraagt. useradd geeft je veel meer parameters, zodat je meer kan instellen (bv. de shell en de homedirectory) en is handig om gebruikers in bulk aan te maken via een bash-script.", o: "Gebruikers beheren",
    uitleg: "Beide vragen sudo-rechten." },
  { v: "Welk commando werd hier uitgevoerd, en wat gebeurt er allemaal?", a: "sudo adduser test. Er wordt een gebruiker test en een groep test (ID 1001) aangemaakt, een homedirectory /home/test met bestanden uit /etc/skel, en daarna vraagt de wizard een paswoord en extra informatie (Full Name, Room Number, …).", o: "Gebruikers beheren", img: "afbeeldingen/DesktopOS_linux_wc3/lx_opl4.png",
    uitleg: "Dit is de wizard van adduser. In de opdracht geef je als paswoord Student2 en als volledige naam testgebruiker; de rest mag blanco. Druk G om te vergroten." },
  { v: "Maak gebruiker test2 met als homedirectory /test/test2 en als shell /bin/false. Welk commando? Wat betekent /bin/false?", a: "$ sudo mkdir /test\n$ sudo useradd -d /test/test2 -s /bin/false test2", o: "Gebruikers beheren", oefening: true,
    uitleg: "-d = homedirectory, -s = shell. /bin/false betekent: de gebruiker mag niet aanloggen in een shell. Controleer in /etc/passwd. Het oplossingendocument gebruikt /home/test2; de opdracht vraagt /test/test2." },
  { v: "Wat doet usermod? Wijzig de home van test2 naar /home/test2 en de shell naar /bin/bash.", a: "$ sudo usermod -d /home/test2 -s /bin/bash test2", o: "Gebruikers beheren", oefening: true,
    uitleg: "usermod wijzigt de instellingen van een bestaande gebruiker (mod = modify). In het oplossingendocument staat '-d /home/test': dat moet /home/test2 zijn." },
  { v: "Hoe wijzig je je eigen paswoord, en dat van een andere gebruiker?", a: "$ passwd\n$ sudo passwd test", o: "Gebruikers beheren", oefening: true,
    uitleg: "Zonder naam wijzig je je eigen paswoord. Voor een andere gebruiker heb je sudo nodig, omdat het een wijziging is die een andere gebruiker raakt." },
  { v: "Optie voor home / shell bij useradd en usermod", a: "-d  /  -s", o: "Gebruikers beheren" },
  { v: "Controleer het resultaat voor test2 in /etc/passwd.", a: "$ grep test2 /etc/passwd", o: "Gebruikers beheren", oefening: true },
  { v: "Wijzig je eigen paswoord.", a: "$ passwd", o: "Gebruikers beheren", oefening: true },
  { v: "Wijzig het paswoord van gebruiker test.", a: "$ sudo passwd test", o: "Gebruikers beheren", oefening: true },
  { v: "Toon als wie je ingelogd bent.", a: "$ whoami", o: "Gebruikers beheren", oefening: true },
  { v: "Probeer als gebruiker test een nieuwe gebruiker test3 aan te maken.", a: "$ sudo adduser test3\n  test is not in the sudoers file.", o: "Gebruikers beheren", oefening: true,
    uitleg: "Geweigerd: test is geen lid van de sudoers-groep." },
  { v: "Ga terug naar de gebruiker student.", a: "$ exit", o: "Gebruikers beheren", oefening: true },
  { v: "Welk commando gebruik je om zelf gebruikers aan te maken?", a: "Het commando adduser.", o: "Gebruikers beheren",
    uitleg: "adduser vraagt alles stap voor stap." },
  { v: "Wat krijg je bij adduser?", a: "Een soort wizard die de belangrijkste informatie van de gebruiker komt vragen.", o: "Gebruikers beheren",
    uitleg: "adduser is gebruiksvriendelijk: het maakt ook meteen de homedirectory aan en vraagt het paswoord." },
  { v: "Welke instellingen kan je bijvoorbeeld met useradd meegeven?", a: "De te gebruiken shell en de locatie van de homedirectory van de gebruiker.", o: "Gebruikers beheren",
    uitleg: "Met de opties -s (shell) en -d (homedirectory)." },
  { v: "Waarvoor is useradd ook zeer handig?", a: "Voor het aanmaken van users in bulk (grote hoeveelheid) via een bash-script.", o: "Gebruikers beheren",
    uitleg: "Een bash-script is een tekstbestand met een reeks commando's die na elkaar uitgevoerd worden." },
  { v: "Maak een nieuwe directory /test\nMaak een nieuwe gebruiker ‘test2’ met als home directory /test/test2 en als shell /bin/false (dit wil zeggen dat de user niet mag aanloggen in een shell)\nVerifieer je resultaat in /etc/passwd", a: "$ sudo mkdir /test\n$ sudo useradd -m -d /test/test2 -s /bin/false test2\n$ grep test2 /etc/passwd", o: "Gebruikers beheren", oefening: true,
    uitleg: "-d = homedirectory, -s = shell, -m = maak de homedirectory ook echt aan. Met /bin/false kan de user niet inloggen in een shell." },
  { v: "Wat is usermod?", a: "Een ander interessant commando voor userbeheer waarmee je instellingen van een gebruiker kan wijzigen ('mod' van modify).", o: "Gebruikers beheren",
    uitleg: "usermod gebruikt grotendeels dezelfde opties als useradd." },
  { v: "Wijzig de instellingen voor gebruiker ‘test2’ zo dat zijn home directory voortaan /home/test2 is en zijn shell /bin/bash\nVerifieer je resultaat in /etc/passwd", a: "$ sudo usermod -d /home/test2 -s /bin/bash test2\n$ grep test2 /etc/passwd", o: "Gebruikers beheren", oefening: true,
    uitleg: "Met -m erbij wordt de inhoud van de oude homedirectory ook verplaatst. In /etc/passwd zijn de laatste twee velden veranderd." },
  { v: "Wat doet passwd zonder gebruikersnaam erachter?", a: "Je wijzigt het paswoord van de gebruiker waarmee je aangelogd bent.", o: "Gebruikers beheren",
    uitleg: "Je moet eerst je huidige paswoord ingeven." },
  { v: "Waar zie je dit dadelijk weergegeven?", a: "In de prompt, die (by default) steeds ook de username toont.", o: "Gebruikers beheren",
    uitleg: "De prompt verandert dan van student@… naar test@…" },
  { v: "Probeer dadelijk ook eens een nieuwe gebruiker aan te maken met de test useraccount. Je zal hiervoor ook sudo moeten gebruiken.", a: "$ su test\n$ sudo adduser test3\n  test is not in the sudoers file.", o: "Gebruikers beheren", oefening: true,
    uitleg: "Dit wordt geweigerd omdat de test-useraccount geen lid is van de sudoers-groep, en zo hoort dat ook." },
  { v: "Wat betekent de shell /bin/false?", a: "De gebruiker mag niet aanloggen in een shell.", o: "Gebruikers beheren" },
  { v: "Wijzig het paswoord van gebruiker test naar Student1. Wat heb je nodig en waarom?", a: "$ sudo passwd test", o: "Gebruikers beheren", oefening: true,
    uitleg: "sudo, omdat het een wijziging voor een andere gebruiker is." },
  { v: "Leg uit: wat is het verschil tussen adduser en useradd?", a: "adduser is een wizard die de belangrijkste info vraagt. useradd heeft veel meer parameters (bv. shell, homedirectory) en is handig voor bulk via scripts.", o: "Gebruikers beheren", examen: true,
    uitleg: "adduser is een gebruiksvriendelijk script (Debian, Ubuntu): het vraagt het paswoord en de informatie, en maakt automatisch de homedirectory aan.\nuseradd is het basiscommando: alles stel je in met opties (-m, -d, -s, …). Daardoor is het geschikt om in een script veel gebruikers tegelijk aan te maken." },
  { v: "Maak gebruiker test2 aan met homedirectory /test/test2 en shell /bin/false.", a: "sudo useradd -m -d /test/test2 -s /bin/false test2", o: "Gebruikers beheren", examen: true,
    uitleg: "sudo: gebruikers aanmaken vraagt root-rechten.\n-m: maak de homedirectory aan.\n-d /test/test2: de homedirectory is /test/test2.\n-s /bin/false: de shell is /bin/false.\ntest2: de gebruikersnaam staat achteraan." },
  { v: "Wat betekent shell /bin/false?", a: "De gebruiker mag niet aanloggen in een shell.", o: "Gebruikers beheren", examen: true,
    uitleg: "/bin/false is een programma dat meteen stopt. Als dat de shell is, wordt de gebruiker bij het inloggen meteen weer uitgelogd.\nZo maak je accounts die geen shell mogen gebruiken, bv. voor een service of een gebruiker die enkel bestanden mag delen." },
  { v: "Wijzig gebruiker test2 zodat de homedirectory /home/test2 is en de shell /bin/bash.", a: "sudo usermod -d /home/test2 -s /bin/bash test2", o: "Gebruikers beheren", examen: true,
    uitleg: "usermod wijzigt een bestaande gebruiker.\n-d /home/test2: nieuwe homedirectory.\n-s /bin/bash: nieuwe shell.\ntest2: de gebruiker staat achteraan.\nMet -m erbij worden de bestanden ook verplaatst naar de nieuwe homedirectory." },
  { v: "Waarvoor dient usermod?", a: "Instellingen van een bestaande gebruiker wijzigen (modify).", o: "Gebruikers beheren", examen: true,
    uitleg: "usermod = user modify. Je wijzigt er o.a. mee:\n-d: de homedirectory\n-s: de shell\n-aG: groepen toevoegen\n-l: de loginnaam\n-L en -U: het account vergrendelen of ontgrendelen" },
  { v: "Geef het commando om je eigen paswoord te wijzigen.", a: "passwd", o: "Gebruikers beheren", examen: true,
    uitleg: "passwd zonder argument wijzigt het paswoord van de gebruiker die ingelogd is. Je geeft eerst het huidige paswoord in, daarna twee keer het nieuwe.\nTijdens het typen zie je geen tekens: dat is normaal." },
  { v: "Geef het commando om het paswoord van gebruiker test te wijzigen.", a: "sudo passwd test", o: "Gebruikers beheren", examen: true,
    uitleg: "passwd met een gebruikersnaam wijzigt het paswoord van die gebruiker. Dat mag enkel root, dus met sudo.\nJe hoeft het oude paswoord van test niet te kennen." },
  { v: "Waarom heb je sudo nodig om het paswoord van test te wijzigen?", a: "Het is een wijziging voor een andere gebruiker.", o: "Gebruikers beheren", examen: true,
    uitleg: "Je eigen paswoord wijzigen mag je zelf. Het paswoord van iemand anders wijzigen heeft impact op een andere gebruiker, en dat mag enkel root.\nVolgens de richtlijn gebruik je sudo voor wijzigingen aan het hele systeem of aan andere gebruikers." },
  // ===== su en wisselen van gebruiker =====
  { v: "Wisselen van gebruiker: su (3)", a: "• su (switch user) opent een shell van een andere gebruiker binnen de shell van je huidige gebruiker.\n• Je ziet het in de prompt: van student@... naar test@...\n• whoami toont ook met welke user je aangelogd bent.\n• Als test een gebruiker aanmaken met sudo wordt geweigerd: test is geen lid van de sudoers-groep.\n• Met exit ga je terug naar de gebruiker student.", o: "su en wisselen van gebruiker", wit: true },
  { v: "Wat doet su, en hoe zie je dat het gelukt is?", a: "su = switch user: je opent een shell van een andere gebruiker binnen de shell van je huidige gebruiker. De prompt verandert, bv. van student@… naar test@….", o: "su en wisselen van gebruiker",
    uitleg: "Ook whoami toont als wie je nu bent ingelogd." },
  { v: "Hoe ga je terug naar je oorspronkelijke gebruiker na su test?", a: "$ exit", o: "su en wisselen van gebruiker", oefening: true,
    uitleg: "Je sluit de shell van test en komt terug in die van student." },
  { v: "Je bent met su ingelogd als test en probeert sudo adduser nieuw. Wat gebeurt er, en waarom?", a: "Het wordt geweigerd, omdat test geen lid is van de sudoers-groep.", o: "su en wisselen van gebruiker",
    uitleg: "Zo hoort het ook: niet elke gebruiker mag gebruikers aanmaken." },
  { v: "Wissel naar gebruiker test.", a: "$ su test", o: "su en wisselen van gebruiker", oefening: true },
  { v: "Probeer eens volgend commando: su test", a: "Je prompt verandert van student@... naar test@... (met de \"…\" afhankelijk van de locatie in de boomstructuur).", o: "su en wisselen van gebruiker",
    uitleg: "De prompt toont gebruiker@computer:map$. Bij root eindigt de prompt op # in plaats van $." },
  { v: "Log in als gebruiker Student vanuit de context van gebruiker Docent.", a: "su Student", o: "su en wisselen van gebruiker", examen: true,
    uitleg: "su = switch user. su Student vraagt het paswoord van Student en opent een shell als Student.\nMet su - Student laad je ook de omgeving van Student (zijn homedirectory en instellingen).\nLet op hoofdletters: Student en student zijn in Linux twee verschillende gebruikers." },
  { v: "Waarvoor staat su?", a: "Switch user.", o: "su en wisselen van gebruiker", examen: true,
    uitleg: "su = switch user (of substitute user). Zonder gebruikersnaam wisselt su naar root.\nIn Ubuntu heeft root standaard geen paswoord, daarom gebruik je daar sudo." },
  { v: "Hoe zie je dat je van gebruiker gewisseld bent?", a: "De prompt verandert (bv. van student@... naar test@...), of via whoami.", o: "su en wisselen van gebruiker", examen: true,
    uitleg: "De prompt toont de huidige gebruiker en computer: student@ubuntu wordt test@ubuntu.\nwhoami toont je huidige loginnaam." },
  { v: "Hoe keer je terug naar de vorige gebruiker na su?", a: "exit", o: "su en wisselen van gebruiker", examen: true,
    uitleg: "su opent een nieuwe shell bovenop de vorige. exit sluit die shell af en je bent terug de vorige gebruiker.\nCtrl+D doet hetzelfde." },
  // ===== Groepen =====
  { v: "Groepen (4)", a: "• Vergelijkbaar met de commando's voor gebruikers: addgroup, groupadd en groupmod.\n• Een gebruiker lid maken van een groep doe je best met usermod.\n• Meer info in de manpages of andere bronnen.\n\nOpdracht: maak de groep testgroup en maak de testgebruiker er lid van.", o: "Groepen", wit: true },
  { v: "Met welke commando's werk je met groepen?", a: "addgroup, groupadd en groupmod.", o: "Groepen",
    uitleg: "Vergelijkbaar met adduser, useradd en usermod voor gebruikers." },
  { v: "Maak de groep testgroup en maak de gebruiker test er lid van. Welke commando's?", a: "$ sudo addgroup testgroup\n$ sudo usermod -aG testgroup test", o: "Groepen", oefening: true,
    uitleg: "-a = append (toevoegen, zonder de andere groepen te verwijderen), -G = de extra groep(en). Zonder -a zou test uit zijn andere extra groepen verdwijnen. Controle: id test." },
  { v: "Groep wijzigen", a: "groupmod", o: "Groepen" },
  { v: "Maak met echo een bestand bestand.txt met tekst erin.", a: "$ echo tekst > bestand.txt", o: "Groepen", oefening: true },
  { v: "Welk commando gebruik je best voor het lid maken?", a: "Het commando usermod.", o: "Groepen",
    uitleg: "usermod -aG groep gebruiker." },
  { v: "Waar kan je meer info vinden?", a: "In de manpages of andere bronnen.", o: "Groepen",
    uitleg: "man usermod, man groupadd." },
  { v: "Maak gebruiker test lid van testgroup met usermod.", a: "$ man usermod\n$ sudo usermod -aG testgroup test", o: "Groepen", oefening: true,
    uitleg: "Zoek de opties eerst op in de manpage." },
  { v: "Controleer of het gelukt is.", a: "$ id test\n$ grep testgroup /etc/group", o: "Groepen", oefening: true },
  { v: "Welke drie commando's bestaan er voor groepen?", a: "addgroup, groupadd en groupmod.", o: "Groepen", examen: true,
    uitleg: "addgroup: het gebruiksvriendelijke script (Debian, Ubuntu).\ngroupadd: het basiscommando.\ngroupmod: een bestaande groep wijzigen, bv. hernoemen met -n.\nLeden toevoegen doe je met usermod -aG." },
  { v: "Maak een groep testgroup aan.", a: "sudo addgroup testgroup (of sudo groupadd testgroup)", o: "Groepen", examen: true,
    uitleg: "Een groep aanmaken heeft impact op het hele systeem, dus sudo.\naddgroup en groupadd doen hetzelfde. De groep komt in /etc/group met een nieuw GID." },
  { v: "Maak gebruiker test lid van testgroup (zonder zijn andere groepen te verliezen).", a: "sudo usermod -aG testgroup test", o: "Groepen", examen: true,
    uitleg: "usermod -aG groep gebruiker:\n-G = de (extra) groepen\n-a = append: toevoegen aan de bestaande groepen\nZonder -a vervangt -G alle extra groepen door enkel testgroup, en verliest test bv. zijn lidmaatschap van sudo.\nDe wijziging geldt pas na opnieuw inloggen." },
  // ===== Ownership =====
  { v: "Ownership (5)", a: "• Elk bestand heeft een eigenaar en een groep; je ziet ze met ls -l.\n• Wie een bestand aanmaakt, wordt automatisch eigenaar en mag de permissies veranderen.\n• chown (change owner): de eigenaar wijzigen.\n• chgrp (change group): de groep wijzigen.\n\nOpdracht: maak als test een bestand, controleer met ls -l, ga terug naar student en maak student eigenaar met chown (met sudo). Controleer opnieuw.", o: "Ownership", wit: true },
  { v: "Wie wordt eigenaar van een nieuw bestand, en wat mag de eigenaar?", a: "Wie het bestand aanmaakt, wordt automatisch eigenaar. Als eigenaar mag je de permissies (rechten) van het bestand veranderen.", o: "Ownership",
    uitleg: "Elk bestand heeft een eigenaar en een groep: zichtbaar met ls -l." },
  { v: "Met welke commando's verander je de eigenaar en de groep van een bestand?", a: "chown (change owner) voor de eigenaar, chgrp (change group) voor de groep.", o: "Ownership",
    uitleg: "Bv. sudo chown student bestand en sudo chgrp testgroup bestand. Recursief voor een hele map: sudo chown -R student map." },
  { v: "De gebruiker test probeert de eigenaar te wijzigen naar student. Wat gaat er mis, en hoe los je het op?", a: "'Operation not permitted': een gewone gebruiker mag de eigenaar niet veranderen. Oplossing: als student (met sudo-rechten) sudo chown student /test/bestand.txt uitvoeren.", o: "Ownership", img: "afbeeldingen/DesktopOS_linux_wc3/lx_opl10.png",
    uitleg: "Het eigenaarschap weggeven of afnemen raakt andere gebruikers, daarom is sudo nodig. Controleer daarna met ls -l." },
  { v: "Zet de stappen van de ownership-opdracht in volgorde.", a: "1. su test (inloggen als test)\n2. touch bestand.txt (bestand maken)\n3. ls -l: eigenaar is test\n4. exit (terug naar student)\n5. sudo chown student bestand.txt\n6. ls -l: eigenaar is nu student", o: "Ownership", oefening: true,
    uitleg: "su test = inloggen als gebruiker test. touch = een bestand maken (kan ook met vi, nano, echo, …). ls -l = lijst met de eigenaar erbij. exit = terug naar student. sudo = als beheerder uitvoeren. chown student bestand.txt = de eigenaar van het bestand veranderen naar student." },
  { v: "Wijzig de eigenaar van bestand.txt naar student.", a: "$ sudo chown student bestand.txt", o: "Ownership", oefening: true },
  { v: "Zoek de syntax van chown op.", a: "$ chown --help\n$ man chown", o: "Ownership", oefening: true },
  { v: "Wat heeft elk bestand?", a: "Een eigenaar en een groep.", o: "Ownership",
    uitleg: "In ls -l zie je ze in kolom 3 (eigenaar) en kolom 4 (groep)." },
  { v: "Hoe krijg je deze informatie te zien?", a: "Met het commando ls -l.", o: "Ownership",
    uitleg: "In de 3de en 4de kolom van ls -l." },
  { v: "Wat mag je als eigenaar?", a: "De permissies van het bestand veranderen.", o: "Ownership",
    uitleg: "Met chmod (zie werkcollege 1)." },
  { v: "Zet de groep van /home/test/bestand_test.txt op testgroup.", a: "$ sudo chgrp testgroup /home/test/bestand_test.txt", o: "Ownership", oefening: true },
  { v: "Voer de ownership-opdracht uit: maak als test een bestand, controleer de eigenaar, ga terug naar student en maak student eigenaar.", a: "$ su test\n$ touch bestand.txt\n$ ls -l bestand.txt\n$ exit\n$ sudo chown student /home/test/bestand.txt\n$ ls -l /home/test/bestand.txt", o: "Ownership", oefening: true,
    uitleg: "Na su test sta je nog in de map waar je was; maak het bestand dus op een plaats waar test mag schrijven, bv. zijn eigen home (cd eerst). Een bestand maken kan ook met vi, nano of echo." },
  { v: "Wie wordt eigenaar van een bestand dat je aanmaakt?", a: "Jij (de gebruiker die het aanmaakt).", o: "Ownership", examen: true,
    uitleg: "Wie een bestand aanmaakt, wordt de owner. De group wordt je primaire groep (bij adduser een groep met je eigen naam).\nJe ziet het met ls -l: de eerste naam is de owner, de tweede de group." },
  { v: "Welk commando wijzigt de eigenaar van een bestand?", a: "chown (change owner)", o: "Ownership", examen: true,
    uitleg: "chown = change owner. Syntax: chown nieuweeigenaar bestand.\nEen bestand aan iemand anders geven mag enkel root, dus meestal met sudo.\nMet -R wijzig je een hele map met alles erin." },
  { v: "Welk commando wijzigt de groep van een bestand?", a: "chgrp (change group)", o: "Ownership", examen: true,
    uitleg: "chgrp = change group. Syntax: chgrp nieuwegroep bestand.\nAls eigenaar mag je de groep wijzigen naar een groep waarin je zelf zit; anders heb je sudo nodig." },
  { v: "Wijzig de owner van bestand.txt naar student.", a: "sudo chown student bestand.txt", o: "Ownership", examen: true,
    uitleg: "sudo chown student bestand.txt: student wordt de nieuwe owner. De group blijft ongewijzigd.\nControleer met ls -l bestand.txt." },
  { v: "Wijzig de groep van bestand.txt naar testgroup.", a: "sudo chgrp testgroup bestand.txt", o: "Ownership", examen: true,
    uitleg: "sudo chgrp testgroup bestand.txt: testgroup wordt de nieuwe group. De owner blijft ongewijzigd.\nHetzelfde kan met chown :testgroup bestand.txt (dubbelpunt ervoor)." },
  { v: "Wijzig owner én groep van bestand.txt in één keer naar student en testgroup.", a: "sudo chown student:testgroup bestand.txt", o: "Ownership", examen: true,
    uitleg: "chown owner:group bestand wijzigt beide in één keer. Owner en group worden gescheiden door een dubbelpunt, zonder spaties." },
  // ===== Compressie =====
  { v: "Compressie met tar (6)", a: "• Ook Linux gebruikt veel compressie, maar vaak met andere algoritmes: vooral gzip (.tar.gz), ook bzip2 (.tar.bz2). Zulke bestanden heten 'tarballs'.\n• Comprimeren: tar -cvzf [naam_archief] [folder_of_bestand]\n• Decomprimeren: tar -xzvf [naam_archief] (c wordt x)\n• Linux kan ook met zip, rar en 7zip. rar en 7zip zijn doorgaans sneller en efficiënter, maar niet overal standaard ondersteund; zip is prima voor een Windows-computer.", o: "Compressie", extra: true, nietTeKennen: true,
    uitleg: "Dit deel is 'good to know'.",
    tabel: [
      ["Optie", "Betekenis"],
      ["c", "create: nieuw compressiebestand"],
      ["x", "extract: uitpakken"],
      ["v", "verbose: vooruitgang tonen"],
      ["z", "gzip-compressie"],
      ["j", "bzip2-compressie"],
      ["f", "file: naam van het archief"]
    ] },
  { v: "Welke compressie-algoritmes zijn populair in Linux, en welke extensies horen erbij?", a: "gzip (.tar.gz) en bzip2 (.tar.bz2). Zulke bestanden heten ook 'tarballs'.", o: "Compressie", extra: true, nietTeKennen: true,
    uitleg: "Je werkt ermee via het commando tar. Dit deel is 'good to know'." },
  { v: "Hoe comprimeer je een map met gzip, en wat betekenen de opties?", a: "$ tar -cvzf archief.tar.gz map", o: "Compressie", oefening: true,
    uitleg: "c = create (nieuw archief), v = verbose (vooruitgang tonen), z = gzip-compressie, f = file (de naam van het archief volgt). Na f komt eerst de naam van het archief, dan wat je wil comprimeren." },
  { v: "Hoe comprimeer je met bzip2 in plaats van gzip?", a: "$ tar -cvjf archief.tar.bz2 map", o: "Compressie", oefening: true,
    uitleg: "Vervang z door j: z = gzip, j = bzip2." },
  { v: "Hoe pak je een .tar.gz-archief uit?", a: "$ tar -xzvf archief.tar.gz", o: "Compressie", oefening: true,
    uitleg: "De c (create) wordt vervangen door x (extract)." },
  { v: "Kan Linux ook met zip, rar en 7zip werken? Waarop moet je letten?", a: "Ja. rar en 7zip zijn meestal sneller en efficiënter, maar worden niet op alle computers standaard ondersteund. zip is prima als je een bestand naar een Windows-computer stuurt.", o: "Compressie",
    uitleg: "Kies je formaat dus in functie van wie het bestand moet openen." },
  { v: "Betekenis c / v / z / j / f / x", a: "create / verbose / gzip / bzip2 / filename / extract", o: "Compressie" },
  { v: "Extensies gzip / bzip2", a: ".tar.gz  /  .tar.bz2", o: "Compressie" },
  { v: "Hoe noemt men dergelijke bestanden?", a: "'Tarballs'.", o: "Compressie",
    uitleg: "tar bundelt meerdere bestanden in één archief (de 'tarball'); gzip of bzip2 maakt dat archief kleiner." },
  { v: "Welk commando gebruik je om met gecomprimeerde bestanden te werken?", a: "Het commando tar.", o: "Compressie",
    uitleg: "tar = tape archive (van vroeger, toen men back-ups op tape maakte)." },
  { v: "Hoe comprimeer je een directory (met alles erin)?", a: "$ tar -cvzf oefeningen.tar.gz oefeningen", o: "Compressie", oefening: true,
    uitleg: "Syntax: tar -cvzf [naam_van_het_te_maken_gecomprimeerde_bestand] [naam_van_de_folder_of_bestand]." },
  { v: "Wat betekent de optie c?", a: "Create een nieuw compressiebestand.", o: "Compressie",
    uitleg: "c = create." },
  { v: "Inmiddels hebben we al wat bestanden gemaakt in eerdere oefeningen. Verzamel deze bestanden in een nieuwe directory in je homefolder.\n2. Comprimeer deze folder met gzip.\n3. Comprimeer deze folder nu ook met bzip2.", a: "$ mkdir ~/oefeningen\n$ mv ~/tekst.txt ~/opdracht.txt ~/oefeningen/\n$ tar -cvzf oefeningen.tar.gz oefeningen\n$ tar -cvjf oefeningen.tar.bz2 oefeningen", o: "Compressie", oefening: true,
    uitleg: "Kies zelf welke bestanden je verzamelt (met cp of mv). Vergelijk de grootte met ls -lh: bzip2 is meestal iets kleiner maar trager." },
  { v: "Wat is er veranderd ten opzichte van het comprimeren?", a: "De c-optie van create is ditmaal vervangen door de -x-optie van extract.", o: "Compressie",
    uitleg: "c (create) wordt x (extract)." },
  { v: "Hernoem of verplaats de originele folder uit de vorige oefening.\n2. Decomprimeer je archief uit de vorige oefening.\n3. Vergelijk inhoud uit de 2 folders.", a: "$ mv oefeningen oefeningen_origineel\n$ tar -xzvf oefeningen.tar.gz\n$ diff -r oefeningen oefeningen_origineel", o: "Compressie", oefening: true,
    uitleg: "diff -r vergelijkt twee mappen inclusief submappen; geen uitvoer betekent: identiek." },
  { v: "Met welke andere compressieformaten kan Linux ook werken?", a: "zip, rar en 7zip.", o: "Compressie",
    uitleg: "Om .zip uit te pakken gebruik je unzip." },
  { v: "Wat is er over rar en 7zip gezegd?", a: "Die laatste 2 zijn doorgaans sneller en efficiënter in compressie.", o: "Compressie",
    uitleg: "Ze comprimeren beter, maar zijn minder universeel." },
  { v: "Waarmee moet je rekening houden?", a: "Voor wie je bestanden bedoeld zijn: zip is prima als je het wil doorsturen naar een Windowscomputer, maar rar en 7zip worden by default nog niet op alle computers ondersteund.", o: "Compressie",
    uitleg: "zip is de veiligste keuze om met Windows-gebruikers te delen." },
  { v: "Gebruikt Linux dezelfde compressie-algoritmes als Windows?", a: "Nee, ook Linux gebruikt veel compressie, maar de algoritmes zijn vaak anders (vooral gzip en bzip2).", o: "Compressie" },
  { v: "Welke extensies horen erbij? Hoe noem je zulke bestanden?", a: ".tar.gz (gzip) en .tar.bz2 (bzip2) · tarballs", o: "Compressie" },
  { v: "Geef de syntax om een directory met gzip te comprimeren.", a: "tar -cvzf <naam_archief> <folder_of_bestand>", o: "Compressie" },
  { v: "Welke optie gebruik je in de plaats van z voor bzip2?", a: "j", o: "Compressie" },
  { v: "Geef de syntax om te decomprimeren. Welke optie vervangt c?", a: "tar -xzvf <naam_archief> · x (extract) vervangt c (create).", o: "Compressie" },
  { v: "Welk formaat kies je om iets naar een Windows-computer te sturen? Waarom?", a: "zip, want rar en 7zip worden nog niet standaard op alle computers ondersteund.", o: "Compressie" },
  { v: "Welke compressiealgoritmen zijn populair in Linux?", a: "gzip (en ook bzip2).", o: "Compressie", examen: true,
    uitleg: "gzip is het meest gebruikte compressieformaat in Linux (extensie .gz). bzip2 comprimeert wat beter maar trager (extensie .bz2).\ngzip en bzip2 comprimeren één bestand. Om een hele map te comprimeren bundel je eerst alles met tar." },
  { v: "Welke extensies hebben tarballs?", a: ".tar.gz (gzip) en .tar.bz2 (bzip2).", o: "Compressie", examen: true,
    uitleg: "Een tarball is een archief gemaakt met tar en daarna gecomprimeerd:\n.tar.gz (ook .tgz): gecomprimeerd met gzip\n.tar.bz2: gecomprimeerd met bzip2\ntar zelf comprimeert niet: het bundelt bestanden en mappen in één bestand." },
  { v: "Comprimeer de folder mijnmap met gzip naar archief.tar.gz.", a: "tar -cvzf archief.tar.gz mijnmap", o: "Compressie", examen: true,
    uitleg: "c = create (maak een archief)\nv = verbose (toon welke bestanden erin gaan)\nz = comprimeer met gzip\nf = de naam van het archief volgt (archief.tar.gz)\nDaarna wat erin moet: mijnmap.\nDe f moet als laatste letter staan, want de naam van het archief volgt erna." },
  { v: "Comprimeer de folder mijnmap met bzip2 naar archief.tar.bz2.", a: "tar -cvjf archief.tar.bz2 mijnmap", o: "Compressie", examen: true,
    uitleg: "Hetzelfde als met gzip, maar met j in plaats van z: j = bzip2.\nc = create, v = verbose, j = bzip2, f = filename (archief.tar.bz2), daarna de map mijnmap." },
  { v: "Decomprimeer archief.tar.gz.", a: "tar -xzvf archief.tar.gz", o: "Compressie", examen: true,
    uitleg: "x = extract (uitpakken)\nz = gzip\nv = verbose\nf = de naam van het archief\nDe bestanden komen in de huidige map terecht. Met -C map kies je een andere map." },
  { v: "Wat betekenen c, x, v, z, j en f bij tar?", a: "c = create, x = extract, v = verbose, z = gzip, j = bzip2, f = filename van het archief.", o: "Compressie", examen: true,
    uitleg: "c = create: een archief maken\nx = extract: een archief uitpakken\nv = verbose: tonen wat er gebeurt\nz = gzip (.tar.gz)\nj = bzip2 (.tar.bz2)\nf = filename: de naam van het archief volgt\nMet t (list) zie je de inhoud zonder uit te pakken." },
  { v: "Welke andere compressieformaten kan Linux aan? Welk is best voor een Windowscomputer?", a: "zip, rar en 7zip. zip is best voor Windows; rar en 7zip zijn niet overal standaard ondersteund.", o: "Compressie", examen: true,
    uitleg: "zip: het formaat dat Windows zelf kan openen, dus het beste om bestanden met een Windowsgebruiker te delen.\nrar en 7zip (.7z): comprimeren vaak beter, maar daarvoor is extra software nodig (in Linux de pakketten unrar en p7zip).\nIn Linux: zip -r archief.zip map en unzip archief.zip." },
  // ===== Netwerk: basisbegrippen =====
  { v: "Wat is een IP-adres, en hoe ziet een IPv4-adres eruit?", a: "Een uniek adres waarmee een toestel op een netwerk gevonden wordt, zoals een huisadres. IPv4: 4 getallen van 0 tot 255, gescheiden door punten, bv. 192.168.1.100.", o: "Netwerk: basisbegrippen", extra: true,
    uitleg: "Twee toestellen in hetzelfde netwerk mogen niet hetzelfde IP-adres hebben, net zoals twee huizen in dezelfde straat niet hetzelfde huisnummer hebben." },
  { v: "Wat doet een subnetmasker, en wat betekent /24?", a: "Het bepaalt welk deel van het IP-adres het netwerk is (de 'straat') en welk deel de computer (het 'huisnummer'). /24 = 255.255.255.0: de eerste 3 getallen zijn het netwerk.", o: "Netwerk: basisbegrippen", extra: true,
    uitleg: "255.255.255.0 bestaat uit 24 enen in binair. 192.168.1.100/24 betekent dus IP 192.168.1.100 met netmask 255.255.255.0. Computers met hetzelfde netwerkdeel (192.168.1.x) kunnen rechtstreeks met elkaar praten." },
  { v: "Wat is de default gateway?", a: "Het toestel (meestal de router) waarnaar verkeer gestuurd wordt dat buiten het eigen netwerk moet, bv. naar het internet.", o: "Netwerk: basisbegrippen", extra: true,
    uitleg: "Zoals een brief naar het buitenland die je naar het postkantoor brengt. Zonder gateway kan je enkel met toestellen in je eigen netwerk praten. Opzoeken in Linux: ip route (de regel 'default via …')." },
  { v: "Wat doet een DNS-server?", a: "Hij zet namen (bv. google.com) om naar IP-adressen, zoals een telefoonboek.", o: "Netwerk: basisbegrippen", extra: true,
    uitleg: "Zonder werkende DNS werkt ping 8.8.8.8 misschien wel, maar ping google.com niet." },
  { v: "Wat is het verschil tussen DHCP en een statisch IP-adres? Waar gebruik je wat?", a: "DHCP: een DHCP-server (vaak de router) geeft automatisch IP, netmask, gateway en DNS. Makkelijk; voor gewone pc's, laptops, gsm's.\nStatisch: je typt alles zelf in een configuratiebestand. Het adres verandert nooit; voor servers, die altijd op hetzelfde adres bereikbaar moeten zijn.", o: "Netwerk: basisbegrippen", extra: true,
    uitleg: "Vergelijk: een hotelkamer die je bij aankomst krijgt (DHCP) tegenover een eigen huis met een vast adres (statisch)." },
  { v: "Wat is het loopbackadres, en hoe heet de adapter?", a: "127.0.0.1 (localhost): een 'nep'-netwerkkaart waarmee de computer met zichzelf praat. De adapter heet lo.", o: "Netwerk: basisbegrippen",
    uitleg: "Elk Linux-systeem heeft die adapter." },
  { v: "Namen van netwerkkaarten / loopback", a: "eth0, eth1 (of enp1s0)  /  lo", o: "Netwerk: basisbegrippen" },
  { v: "Welke adapter is er voor het loopbackadres?", a: "Een adapter met de naam 'lo'.", o: "Netwerk: basisbegrippen",
    uitleg: "Loopback (lo, adres 127.0.0.1) is een virtuele netwerkkaart waarmee de computer met zichzelf praat." },
  { v: "Bekijk welke netwerkkaarten er in je systeem actief zijn.", a: "$ ip a", o: "Netwerk: basisbegrippen", oefening: true,
    uitleg: "Op oudere systemen: ifconfig. Je ziet lo en je ethernetkaart (bv. eth0 of enp1s0) met de status UP en het IP-adres achter inet." },
  // ===== Netwerkconfiguratie in Linux =====
  { v: "Netwerkinstellingen (7)", a: "• Linux wordt vooral gebruikt in netwerk- en serveromgevingen: basiscommando's rond netwerken zijn nodig.\n• Sterkte én zwakte: veel varianten voor dezelfde taak. Voor netwerken:\n– /etc/network/interfaces: de traditionele manier\n– netplan: standaard in Ubuntu sinds 18.04\n– NetworkManager: vooral bij RedHat-distributies (zoals CentOS)\n• Overschakelen is meestal niet al te ingewikkeld. De les focust op de traditionele manier en netplan.\n• Netwerkkaarten heten eth0, eth1, ...; de loopback-adapter heet lo. Recentere distributies: namen zoals enp1s0.\n• Bekijken: ifconfig (oud) of ip a (recent).\n\nOpdracht: bekijk welke netwerkkaarten actief zijn.", o: "Netwerkconfiguratie in Linux", wit: true },
  { v: "Waarom moet je netwerkcommando's kennen in Linux?", a: "Omdat Linux vooral gebruikt wordt in netwerk- en serveromgevingen.", o: "Netwerkconfiguratie in Linux",
    uitleg: "Een server moet vaak een vast IP-adres krijgen, en dat stel je zelf in." },
  { v: "Wat is zowel een sterkte als een zwakte van Linux bij netwerkconfiguratie?", a: "Er bestaan veel varianten om dezelfde taak uit te voeren, elk met voor- en nadelen. Dat geeft keuze, maar zorgt ook voor een wildgroei aan toepassingen en meer complexiteit.", o: "Netwerkconfiguratie in Linux",
    uitleg: "Overschakelen naar een ander systeem is meestal niet al te ingewikkeld, ongeacht de distributie." },
  { v: "Welke 3 manieren om het netwerk te configureren bestaan er, en waar worden ze gebruikt?", a: "1. /etc/network/interfaces: de traditionele manier (tekstbestand).\n2. netplan: standaard in Ubuntu sinds 18.04 (en afgeleiden), met een .yaml-bestand in /etc/netplan.\n3. NetworkManager: vooral bij RedHat-distributies, zoals CentOS.", o: "Netwerkconfiguratie in Linux",
    uitleg: "De cursus focust op de traditionele manier en op netplan." },
  { v: "Welke namen krijgen netwerkkaarten in Linux?", a: "Klassiek eth0, eth1, … (beginnend bij 0); de loopback-adapter heet lo. Een systeem met 2 netwerkkaarten heeft dus eth0, eth1 en lo. Recentere distributies bouwen de naam op vanuit het bestand in de sys-folder, bv. enp1s0.", o: "Netwerkconfiguratie in Linux",
    uitleg: "Op je eigen VM heet je kaart dus waarschijnlijk niet eth0." },
  { v: "Met welk commando bekijk je de netwerkinstellingen?", a: "ifconfig op oudere distributies, ip a (ip address) op recentere distributies.", o: "Netwerkconfiguratie in Linux",
    uitleg: "Gateway: ip route. DNS-server: resolvectl status." },
  { v: "Dit is een stukje uitvoer van ip a. Wat is de naam van de kaart, het IP-adres en het subnetmasker?", a: "Kaart: eth0\nIP-adres: 192.168.1.5\nSubnetmasker: /24 = 255.255.255.0", o: "Netwerkconfiguratie in Linux", img: "afbeeldingen/DesktopOS_linux_wc3/lx_opl12.png",
    uitleg: "Je leest het af op de regel 'inet 192.168.1.5/24 … eth0'. 'state UP' betekent dat de kaart actief is. 'link/ether' is het MAC-adres. Druk G om te vergroten." },
  { v: "Bekijk de actieve netwerkkaarten.", a: "$ ip a", o: "Netwerkconfiguratie in Linux", oefening: true,
    uitleg: "Op oudere distributies: ifconfig." },
  { v: "Waarvoor wordt Linux voornamelijk gebruikt?", a: "In netwerk- en serveromgevingen. Het is dan ook noodzakelijk om wat basiscommando's rond netwerken te kennen.", o: "Netwerkconfiguratie in Linux",
    uitleg: "De meeste servers ter wereld draaien Linux." },
  { v: "Wat is goed om weten over het overschakelen?", a: "Het is vaak niet al te ingewikkeld om, ongeacht van de distributie waarin je aan het werken bent, over te schakelen naar een ander systeem.", o: "Netwerkconfiguratie in Linux",
    uitleg: "De principes (IP-adres, gateway, DNS) zijn overal dezelfde." },
  { v: "Welke adapters heeft een systeem met 2 netwerkkaarten?", a: "eth0 en eth1, en een adapter lo.", o: "Netwerkconfiguratie in Linux",
    uitleg: "Plus lo (loopback)." },
  { v: "Wat is de noot over recentere linux-distributies?", a: "In veel van de recentere distributies wordt de naam van de netwerkkaart opgebouwd vanuit de naam van het bestand in de sys-folder horende bij de netwerkkaart. Dit geeft namen zoals \"enp1s0\".", o: "Netwerkconfiguratie in Linux",
    uitleg: "enp1s0 = ethernet, PCI-bus 1, slot 0." },
  { v: "Is het moeilijk om over te schakelen naar een ander systeem voor netwerkconfiguratie?", a: "Nee, ongeacht de distributie is dat vaak niet al te ingewikkeld.", o: "Netwerkconfiguratie in Linux" },
  { v: "Welke naam krijgen ethernetkaarten standaard? En het loopbackadres?", a: "eth0, eth1… en lo voor loopback.", o: "Netwerkconfiguratie in Linux", examen: true,
    uitleg: "In oudere distributies heten de ethernetkaarten eth0, eth1, … in de volgorde waarin ze gevonden worden.\nlo is de loopback-interface met het adres 127.0.0.1: de computer zelf. Verkeer naar lo verlaat de computer nooit." },
  { v: "Welk soort naam krijgt een netwerkkaart in recentere distributies?", a: "Een naam uit de sys-folder, bv. enp1s0.", o: "Netwerkconfiguratie in Linux", examen: true,
    uitleg: "Recentere distributies gebruiken voorspelbare namen (predictable network interface names), gebaseerd op de plaats van de kaart in de hardware: enp1s0 = ethernet, PCI-bus 1, slot 0.\nDe naam blijft zo dezelfde, ook als je een kaart toevoegt. In /sys/class/net zie je de namen." },
  { v: "Met welk commando bekijk je de netwerkinstellingen (oud en nieuw)?", a: "ifconfig (oudere distributies) en ip a (recentere).", o: "Netwerkconfiguratie in Linux", examen: true,
    uitleg: "ifconfig is het oude commando (pakket net-tools), niet meer standaard geïnstalleerd in recente distributies.\nip a (ip address) is het nieuwe commando: het toont per interface het IP-adres, het subnet (bv. /24) en het MAC-adres.\nIn Windows is het equivalent ipconfig." },
  { v: "Noem de drie manieren om het netwerk te configureren.", a: "/etc/network/interfaces (traditioneel), netplan (Ubuntu sinds 18.04) en NetworkManager (RedHat/CentOS).", o: "Netwerkconfiguratie in Linux", examen: true,
    uitleg: "/etc/network/interfaces: de traditionele manier (Debian, oudere Ubuntu).\nnetplan: Ubuntu sinds 18.04, met .yaml-bestanden in /etc/netplan.\nNetworkManager: vooral bij Red Hat, CentOS en desktops, met de tool nmcli of de grafische instellingen." },
  // ===== /etc/network/interfaces =====
  { v: "Netwerk via /etc/network/interfaces (7.1)", a: "• Werkt niet op jullie systeem (Ubuntu gebruikt netplan): beschouw het als theorie.\n• De instellingen staan in de textfile /etc/network/interfaces; bekijken met cat, nano, vi, ...\n• Standaard via dhcp: auto eth0 en iface eth0 inet dhcp (plus auto lo en iface lo inet loopback).\n• Vast IP (gebruikelijk voor een server): iface eth0 inet static met address, netmask en gateway.\n• Daarna de network service herstarten: sudo systemctl restart networking\n• DNS-server: in /etc/resolv.conf met nameserver [ip-adres van de dns-server].", o: "/etc/network/interfaces", wit: true },
  { v: "In welk bestand staan de netwerkinstellingen bij de traditionele manier, en werkt dat op jullie VM?", a: "In /etc/network/interfaces. Het werkt niet op jullie Ubuntu-VM, omdat die netplan gebruikt; je moet het wel als theorie kennen.", o: "/etc/network/interfaces",
    uitleg: "Bekijken kan met cat, nano, vi, …" },
  { v: "Wat betekenen deze regels in /etc/network/interfaces?\nauto eth0\niface eth0 inet dhcp\niface lo inet loopback", a: "auto eth0: activeer eth0 automatisch bij het opstarten.\niface eth0 inet dhcp: eth0 krijgt zijn IPv4-instellingen via DHCP.\niface lo inet loopback: lo is de loopback-adapter.", o: "/etc/network/interfaces",
    uitleg: "inet = IPv4. Regels met # zijn commentaar. 'source /etc/network/interfaces.d/*' leest ook alle bestanden uit die map in." },
  { v: "Hoe stel je in /etc/network/interfaces een vast IP-adres in voor eth0 (voorbeeld uit de cursus)?", a: "auto lo eth0\niface lo inet loopback\niface eth0 inet static\n    address 192.168.1.100\n    netmask 255.255.255.0\n    gateway 192.168.1.1", o: "/etc/network/interfaces",
    uitleg: "dhcp wordt static, en je geeft zelf address (IP), netmask en gateway. 'auto lo eth0' activeert beide adapters in één regel." },
  { v: "Wat moet je doen na een aanpassing in /etc/network/interfaces?", a: "$ sudo systemctl restart networking", o: "/etc/network/interfaces", oefening: true,
    uitleg: "sudo is nodig omdat het een instelling is die het hele systeem raakt." },
  { v: "Waar stel je bij de traditionele manier de DNS-server in, en met welke syntax?", a: "In /etc/resolv.conf, met: nameserver [ip-adres van de dns-server], bv. nameserver 172.20.0.253", o: "/etc/network/interfaces",
    uitleg: "Bij netplan staat DNS in hetzelfde .yaml-bestand als IP en gateway; traditioneel apart in /etc/resolv.conf." },
  { v: "Traditioneel configbestand", a: "/etc/network/interfaces", o: "/etc/network/interfaces" },
  { v: "eth0 via DHCP (interfaces)", a: "auto eth0\niface eth0 inet dhcp", o: "/etc/network/interfaces" },
  { v: "Welke manieren zijn er om netwerken te configureren?", a: "De traditionele manier via de textfile /etc/network/interfaces.\nDe nieuwe manier, netplan, sinds 18.04 de standaard bij Ubuntudistributies (en derivaten).\nNetworkManager, de manier die eerder bij RedHat distributies (zoals CentOS) gebruikelijk is.", o: "/etc/network/interfaces",
    uitleg: "Ubuntu (en derivaten) gebruiken netplan; RedHat-distributies zoals CentOS gebruiken NetworkManager." },
  { v: "Waarom werkt deze methode niet op ons systeem?", a: "Ubuntu maakt gebruik van netplan. Beschouw het dus als een stukje theorie.", o: "/etc/network/interfaces",
    uitleg: "Ubuntu gebruikt netplan; deze methode is dus theorie." },
  { v: "Hoe kan je deze bekijken?", a: "Via tools zoals cat, nano, vi...", o: "/etc/network/interfaces",
    uitleg: "Bv. cat /etc/network/interfaces." },
  { v: "Hoe ziet een standaard configuratie via dhcp er meestal uit?", a: "# This file describes the network interfaces available on your system\n# and how to activate them. For more information, see interfaces(5).\nsource /etc/network/interfaces.d/*\n# The loopback network interface\nauto lo\niface lo inet loopback\n# The primary network interface\nauto eth0\niface eth0 inet dhcp", o: "/etc/network/interfaces",
    uitleg: "dhcp = de netwerkkaart krijgt automatisch een IP-adres van een DHCP-server. auto = de kaart wordt bij het opstarten automatisch geactiveerd." },
  { v: "Welk tekstbestand wordt gebruikt voor het instellen van de dns-server?", a: "/etc/resolv.conf", o: "/etc/network/interfaces",
    uitleg: "resolv = resolver: het onderdeel dat namen omzet naar IP-adressen." },
  { v: "Wat is de syntax daarvan?", a: "Bijzonder eenvoudig: Nameserver [ip-adres van de dns-server]", o: "/etc/network/interfaces",
    uitleg: "In het bestand schrijf je de regel in kleine letters: nameserver 8.8.8.8. DNS vertaalt namen (zoals google.com) naar IP-adressen." },
  { v: "Noem de drie manieren om het netwerk in Linux te configureren, en waar ze gebruikt worden.", a: "/etc/network/interfaces (traditioneel) · netplan (standaard in Ubuntu sinds 18.04) · NetworkManager (vooral RedHat-distributies zoals CentOS).", o: "/etc/network/interfaces" },
  { v: "Wat betekenen in /etc/network/interfaces de regels die met # beginnen, en de regel source /etc/network/interfaces.d/* ?", a: "# = commentaar · source laadt ook alle configuratiebestanden uit de map /etc/network/interfaces.d.", o: "/etc/network/interfaces" },
  { v: "Voor welk soort machine geef je een netwerkkaart gewoonlijk een vast IP-adres?", a: "Voor een server.", o: "/etc/network/interfaces" },
  { v: "In welk bestand staat de traditionele netwerkconfiguratie?", a: "/etc/network/interfaces", o: "/etc/network/interfaces", examen: true,
    uitleg: "In /etc/network/interfaces stel je per interface in of ze een IP-adres krijgt via DHCP of een vast (static) adres.\nNa een wijziging herstart je de netwerkservice: sudo systemctl restart networking." },
  { v: "Welke regel zet eth0 op dhcp in /etc/network/interfaces?", a: "iface eth0 inet dhcp", o: "/etc/network/interfaces", examen: true,
    uitleg: "iface eth0: de instellingen voor eth0.\ninet: IPv4 (inet6 is IPv6).\ndhcp: het IP-adres wordt automatisch gevraagd aan een DHCP-server.\nMeestal staat erboven ook auto eth0, zodat de interface bij het opstarten actief wordt." },
  { v: "Welke regels geven eth0 een vast IP 192.168.1.100/24 met gateway 192.168.1.1 in /etc/network/interfaces?", a: "iface eth0 inet static / address 192.168.1.100 / netmask 255.255.255.0 / gateway 192.168.1.1", o: "/etc/network/interfaces", examen: true,
    uitleg: "iface eth0 inet static: eth0 krijgt een vast IPv4-adres.\naddress: het IP-adres.\nnetmask: het subnetmasker; /24 = 255.255.255.0.\ngateway: de router naar andere netwerken.\nDe regels onder iface springen in." },
  { v: "Hoe herstart je de network service na het wijzigen van /etc/network/interfaces?", a: "sudo systemctl restart networking", o: "/etc/network/interfaces", examen: true,
    uitleg: "systemctl beheert services. restart stopt de service networking en start ze opnieuw, zodat de nieuwe instellingen uit /etc/network/interfaces gelezen worden.\nDat vraagt root-rechten, dus sudo. Via SSH verlies je de verbinding als de instellingen fout zijn." },
  { v: "In welk bestand stel je de DNS-server in (traditioneel)? Wat is de syntax?", a: "/etc/resolv.conf met: nameserver [ip-adres]", o: "/etc/network/interfaces", examen: true,
    uitleg: "/etc/resolv.conf bevat de DNS-servers die het systeem gebruikt, één per regel:\nnameserver 8.8.8.8\nnameserver 1.1.1.1\nIn recente Ubuntu wordt dit bestand automatisch beheerd (systemd-resolved); je stelt DNS dan in via netplan." },
  // ===== netplan =====
  { v: "Netwerk via netplan (7.2)", a: "• Standaard in Ubuntu sinds 18.04.\n• De instellingen staan in een .yaml-bestand in /etc/netplan. De naam is niet belangrijk, de extensie .yaml wel; vaak 00-installer-config.yaml.\n• Bekijken met cat, nano, vi, ...\n• DHCP voor eth0: dhcp4: true onder ethernets: eth0:.\n• Vast IP: addresses (bv. 192.168.1.100/24), gateway4 (192.168.1.1) en nameservers met addresses (de DNS-servers).", o: "netplan", wit: true,
    uitleg: "Let op de inspringing in een .yaml-bestand: gebruik spaties, geen tabs." },
  { v: "Waar staan de netplan-instellingen? Is de naam van het bestand belangrijk?", a: "In een .yaml-bestand in de map /etc/netplan. De naam maakt niet uit, zolang de extensie .yaml is. Als het netwerk bij de installatie werd ingesteld, heet het vaak 00-installer-config.yaml.", o: "netplan",
    uitleg: "Bekijken met cat, nano, vi, …" },
  { v: "Waarop moet je extra letten bij een .yaml-bestand?", a: "Op de inspringing: YAML gebruikt spaties om de structuur aan te geven (wat meer naar rechts staat, hoort bij de regel erboven). Gebruik spaties, geen tabs, en wees nauwkeurig.", o: "netplan",
    uitleg: "Eén spatie te veel of te weinig en de configuratie werkt niet." },
  { v: "Geef het netplan-voorbeeld voor eth0 met DHCP.", a: "network:\n  ethernets:\n    eth0:\n      dhcp4: true\n  version: 2", o: "netplan",
    uitleg: "dhcp4: true = gebruik DHCP voor IPv4 (de 4 staat voor IPv4). version: 2 = de versie van het netplan-formaat. Op je eigen VM vervang je eth0 door de echte naam (bv. enp1s0)." },
  { v: "Geef het netplan-voorbeeld met een vast IP (192.168.1.100/24, gateway 192.168.1.1, DNS 172.20.0.253 en 172.20.0.254).", a: "network:\n  ethernets:\n    eth0:\n      addresses:\n        - 192.168.1.100/24\n      gateway4: 192.168.1.1\n      nameservers:\n        addresses:\n          - 172.20.0.253\n          - 172.20.0.254\n  version: 2", o: "netplan",
    uitleg: "Het IP-adres staat mét het subnetmasker in /-notatie. Het streepje '-' betekent 'een element van een lijst'. dhcp4: true staat er niet meer, want je stelt alles zelf in. (Extra: in nieuwere Ubuntu-versies geeft gateway4 een waarschuwing en schrijft men routes: - to: default via: …; volg voor het examen de cursus.)" },
  { v: "Wat stelt deze netplan-configuratie in?", a: "Een vast (statisch) IP-adres voor eth0: IP 192.168.1.5 met subnetmasker /24 (255.255.255.0), default gateway 192.168.1.1, en twee DNS-servers: 172.20.0.253 en 172.20.0.254.", o: "netplan", img: "afbeeldingen/DesktopOS_linux_wc3/lx_opl13.png",
    uitleg: "Dit is de oplossing van de opdracht: hetzelfde IP dat je via DHCP kreeg (hier 192.168.1.5), nu vast ingesteld. De eerste regel met # is commentaar ('written by subiquity' = de Ubuntu-installer)." },
  { v: "Hoe noteer je in netplan het IP-adres 192.168.1.100 met netmask 255.255.255.0, en met welke sleutel stel je de gateway in?", a: "Onder addresses: als - 192.168.1.100/24\nDe gateway met gateway4: 192.168.1.1", o: "netplan",
    uitleg: "/24 = 255.255.255.0 (24 enen). De 4 in gateway4 staat voor IPv4." },
  { v: "Map met netplan-bestanden", a: "/etc/netplan   (extensie .yaml)", o: "netplan" },
  { v: "Op welke twee manieren focust deze les?", a: "Op de traditionele manier die in verschillende Linux toepassingen nog regelmatig voorkomt, en netplan.", o: "netplan",
    uitleg: "En niet op NetworkManager." },
  { v: "Sinds welke versie gebruiken Ubuntu distributies by default netplan?", a: "Sinds versie 18.04.", o: "netplan",
    uitleg: "Ubuntu 18.04 = april 2018." },
  { v: "Waar worden de instellingen van de netwerkkaarten bijgehouden?", a: "In een .yaml bestand in de folder /etc/netplan.", o: "netplan",
    uitleg: "In /etc/netplan." },
  { v: "Hoe belangrijk is de naam van dit bestand?", a: "Op zich niet zo belangrijk, zolang de extensie maar .yaml is.", o: "netplan",
    uitleg: "Alleen de extensie .yaml telt." },
  { v: "Hoe heet dit bestand vaak?", a: "\"00-installer-config.yaml\", indien de netwerkconfiguratie bij de installatie werd ingesteld.", o: "netplan",
    uitleg: "netplan leest ALLE .yaml-bestanden in /etc/netplan. Geef een backup daarom een andere extensie (bv. .bak), anders wordt hij mee toegepast." },
  { v: "Wat is een handige extra feature van netplan?", a: "Je kan de nieuwe instellingen eerst testen alvorens ze definitief toe te passen.", o: "netplan",
    uitleg: "netplan try." },
  { v: "Hoe kan je testen of de configuratie naar behoren werkt?", a: "Bijvoorbeeld door een nieuw terminalvenster te openen en te zien of je de juiste configuratie hebt bekomen (bijvoorbeeld via 'ip a') en deze te testen (bijvoorbeeld via een ping).", o: "netplan",
    uitleg: "ip a = je IP-adres controleren. ping = testen of een ander toestel bereikbaar is." },
  { v: "Sinds welke Ubuntu-versie is netplan de standaard?", a: "18.04", o: "netplan" },
  { v: "Sinds welke Ubuntuversie is netplan standaard?", a: "18.04", o: "netplan", examen: true,
    uitleg: "Ubuntu 18.04 (april 2018) is de eerste versie waarin netplan standaard is. Het versienummer van Ubuntu is jaar.maand van de release." },
  { v: "Waar staan de netplan-instellingen en welke extensie heeft het bestand?", a: "In /etc/netplan, een .yaml-bestand (bv. 00-installer-config.yaml).", o: "netplan", examen: true,
    uitleg: "De netplan-instellingen staan in /etc/netplan, in een bestand met extensie .yaml, bv. 00-installer-config.yaml of 50-cloud-init.yaml.\nYAML gebruikt inspringing met spaties (geen tabs) om de structuur aan te geven. Een fout in de inspringing geeft een fout bij netplan try of netplan apply." },
  { v: "Welke regel in netplan zet eth0 op dhcp?", a: "dhcp4: true (onder network: ethernets: eth0:)", o: "netplan", examen: true,
    uitleg: "In netplan:\nnetwork:\n  ethernets:\n    eth0:\n      dhcp4: true\ndhcp4: true = vraag een IPv4-adres via DHCP. Voor een vast adres zet je dhcp4: false en vul je addresses in." },
  { v: "Welke sleutels gebruik je in netplan voor vast IP, gateway en DNS?", a: "addresses: (bv. - 192.168.1.100/24), gateway4: 192.168.1.1, nameservers: addresses: (bv. - 172.20.0.253)", o: "netplan", examen: true,
    uitleg: "addresses: lijst van vaste IP-adressen met subnet in CIDR-notatie, bv. - 192.168.1.100/24.\ngateway4: de default gateway (in nieuwere versies via routes:).\nnameservers: met daaronder addresses: de DNS-servers, bv. - 172.20.0.253.\nElk item van een lijst begint met een streepje." },
  // ===== netplan try =====
  { v: "netplan try: waarom eerst testen?", a: "Je kan nieuwe instellingen eerst testen voor je ze definitief toepast. Vooral nuttig over SSH, want SSH gebruikt zelf het netwerk.", o: "netplan try", wit: true },
  { v: "sudo netplan try", a: "• Je krijgt 120 seconden om te controleren, bv. in een nieuw terminalvenster met ip a en een ping.\n• Werkt alles: ENTER in het venster van netplan try.\n• Anders keert netplan terug naar de oude configuratie.", o: "netplan try", wit: true },
  { v: "netplan try: toch een foute configuratie aanvaard", a: "Dan werkt SSH niet meer. Oplossen kan enkel fysiek aan de machine of via de console view in de vmm-console.", o: "netplan try", wit: true },
  { v: "Welke handige extra feature heeft netplan, en met welk commando?", a: "Je kan nieuwe instellingen eerst testen voor je ze definitief toepast: sudo netplan try", o: "netplan try",
    uitleg: "Je krijgt 120 seconden om te controleren of alles werkt." },
  { v: "Hoe verloopt sudo netplan try?", a: "1. Je voert sudo netplan try uit.\n2. Je krijgt 120 seconden om te controleren: open een nieuw terminalvenster, kijk met ip a of je het juiste adres hebt en test met ping.\n3. Werkt alles? Druk ENTER in het venster van netplan try: de instellingen worden definitief.\n4. Druk je niet op ENTER, dan keert netplan na 120 seconden automatisch terug naar de oude configuratie.", o: "netplan try",
    uitleg: "Test bv. ping 8.8.8.8 (werkt de verbinding?) en ping google.com (werkt DNS?)." },
  { v: "Waarom is netplan try vooral nuttig als je via SSH werkt?", a: "SSH gebruikt zelf het netwerk. Activeer je een foute configuratie, dan valt het netwerk weg en daarmee ook je SSH-verbinding: je kan het probleem dan niet meer op afstand oplossen.", o: "netplan try",
    uitleg: "Met try keert netplan vanzelf terug naar de oude instellingen als je niet op ENTER kan drukken." },
  { v: "Je hebt per ongeluk een foute netwerkconfiguratie aanvaard en SSH werkt niet meer. Hoe los je het op?", a: "Enkel fysiek aan de Linux-machine, of in jullie geval via de console view in de vmm-console (Virtual Machine Manager).", o: "netplan try",
    uitleg: "Daarom: altijd eerst een backup maken en testen met netplan try." },
  { v: "Wat is het verschil tussen sudo netplan try en sudo netplan apply?", a: "try test de configuratie eerst (120 seconden, met automatisch terugkeren). apply past de configuratie meteen toe, zonder testperiode.", o: "netplan try",
    uitleg: "apply is handig als je zeker bent, maar riskanter. (apply staat in de extra uitleg, niet in de werkcollegetekst.)" },
  { v: "Zet de stappen van de netplan-opdracht in volgorde.", a: "1. Naam van je kaart en DHCP-IP zoeken: ip a\n2. De instellingen bekijken in /etc/netplan\n3. Het .yaml-bestand kopiëren als backup\n4. Het origineel aanpassen naar een vast IP (hetzelfde IP als via DHCP)\n5. Testen met sudo netplan try; niet ok → laten terugkeren, ok → ENTER\n6. Terug naar DHCP zetten, opnieuw testen en aanvaarden", o: "netplan try", oefening: true,
    uitleg: "ip a = je netwerkkaarten en IP-adressen tonen. /etc/netplan = de map met de netwerkinstellingen. cp … .bak = een backup maken (laat ze niet op .yaml eindigen, anders leest netplan beide bestanden). sudo netplan try = de nieuwe instellingen testen: niet ok → ze worden vanzelf teruggezet, ok → ENTER. Backup: sudo cp /etc/netplan/00-installer-config.yaml /etc/netplan/00-installer-config.yaml.bak." },
  { v: "Test tijdens sudo netplan try in een nieuw venster of de configuratie werkt.", a: "$ ip a\n$ ping 192.168.1.1", o: "netplan try", oefening: true,
    uitleg: "ip a: heb je het juiste adres? ping: is bv. je gateway bereikbaar?" },
  { v: "Met welk commando test en activeer je je netplan configuratie?", a: "$ sudo netplan try", o: "netplan try", oefening: true,
    uitleg: "Bij een fout, of als je niets doet, keert netplan na 120 seconden automatisch terug naar de vorige configuratie." },
  { v: "Hoeveel tijd krijg je om te verifiëren?", a: "120 seconden.", o: "netplan try",
    uitleg: "2 minuten." },
  { v: "Wat doe je als alles werkt zoals verwacht?", a: "Druk op ENTER in het venster waar je het commando 'sudo netplan try' hebt uitgevoerd. De netwerkinstellingen zullen definitief worden toegepast.", o: "netplan try",
    uitleg: "Zonder ENTER keert netplan terug naar de oude configuratie." },
  { v: "Zoek de naam van je netwerkkaart en het IP-adres (dat je bekomen hebt via DHCP).\n2. Bekijk de netwerkinstellingen van jouw netwerkkaart in /etc/netplan.\n3. Copieer het .yaml bestand naar een nieuw bestand op dezelfde locatie met een andere naam naar keuze. Dit zal je backup worden.\n4. Wijzig het originele bestand zodanig dat jouw netwerkkaart voortaan hetzelfde IP-adres dat je verkregen hebt via DHCP vanaf nu via een vast IP-adres ingesteld krijgt. Gebruik hiervoor het voorbeeld van hierboven als leidraad.\n5. Probeer de nieuwe configuratie uit en TEST deze. Indien de test niet ok is, laat netplan automatisch terugkeren naar de oorspronkelijke configuratie. (Moest je per ongeluk toch een foute configuratie hebben aanvaard, zal je ssh-verbinding ook niet meer werken. De enige manier om dit probleem dan op te lossen is fysiek aan de linux machine, of in ons geval, via de console view in de vmm-console) Indien de test succesvol is, aanvaard de instellingen.\n6. Zet de instellingen van je eth0-kaart terug naar dhcp.\nProbeer de nieuwe configuratie uit en TEST. Indien de test succesvol is, aanvaard de instellingen.", a: "$ ip a\n$ cat /etc/netplan/00-installer-config.yaml\n$ sudo cp /etc/netplan/00-installer-config.yaml /etc/netplan/00-installer-config.yaml.bak\n$ sudo nano /etc/netplan/00-installer-config.yaml\n$ sudo netplan try\n  ENTER (als de test in een tweede terminal ok is)", o: "netplan try", oefening: true,
    uitleg: "Stap 4: vervang dhcp4: true door addresses, gateway4 en nameservers zoals in het voorbeeld, met je eigen IP-adres. Stap 6: zet dhcp4: true terug, opnieuw sudo netplan try, testen en ENTER. Geef je backup een andere extensie dan .yaml (bv. .bak), anders past netplan ook die toe." },
  { v: "Wat als je per ongeluk toch een foute configuratie hebt aanvaard?", a: "Dan zal je ssh-verbinding ook niet meer werken. De enige manier om dit probleem dan op te lossen is fysiek aan de linux machine, of in ons geval, via de console view in de vmm-console.", o: "netplan try",
    uitleg: "De VMM-console werkt los van het netwerk van de VM, zoals een scherm aan de computer." },
  { v: "Hoeveel tijd krijg je om te testen? Hoe aanvaard je de instellingen?", a: "120 seconden · druk ENTER in het venster van netplan try. Doe je niets, dan keert netplan terug naar de oude configuratie.", o: "netplan try" },
  { v: "Hoe test je tijdens die 120 seconden of alles werkt?", a: "In een nieuw terminalvenster: ip a (juiste configuratie?) en ping (werkt het?).", o: "netplan try" },
  { v: "Geef het commando om een netplan-configuratie te testen en eventueel toe te passen.", a: "sudo netplan try", o: "netplan try", examen: true,
    uitleg: "netplan try past de nieuwe configuratie tijdelijk toe en vraagt een bevestiging.\nDruk je op Enter, dan blijft de nieuwe configuratie. Doe je niets, dan zet netplan na 120 seconden de oude terug.\nnetplan apply past de configuratie meteen toe, zonder vangnet." },
  { v: "Hoeveel tijd krijg je bij netplan try en wat gebeurt er als je niets doet?", a: "120 seconden; zonder bevestiging (ENTER) keert hij terug naar de oude configuratie.", o: "netplan try", examen: true,
    uitleg: "Je krijgt 120 seconden om met Enter te bevestigen. Bevestig je niet, dan gaat netplan terug naar de vorige configuratie (rollback).\nZo verlies je je server niet als de nieuwe instellingen fout zijn." },
  { v: "Waarom is netplan try vooral handig via SSH?", a: "SSH gebruikt zelf het netwerk; bij een foute configuratie verlies je de verbinding en kan je het niet meer oplossen.", o: "netplan try", examen: true,
    uitleg: "Via SSH werk je over het netwerk. Is de nieuwe netwerkconfiguratie fout, dan valt de verbinding weg en kan je niets meer typen om het te herstellen.\nMet netplan try kan je niet bevestigen als de verbinding weg is, dus na 120 seconden komt de oude, werkende configuratie automatisch terug." },
  // ===== Software: package manager =====
  { v: "Software beheren met de package manager (8)", a: "• Een van de sterkste kanten van Linux.\n• De package manager houdt een database bij van de pakketten op online servers (repositories) en vergelijkt die met de lokale database van wat geïnstalleerd is.\n• Hij zoekt zelf de dependencies en installeert of verwijdert ze mee.\n• Alle software, inclusief het OS, update je met 1 commando. Andere OS'en proberen dat met 'stores' of tools zoals Chocolatey.\n• Debian-distro's: apt-get, of apt (met een progressiebalk). Vereist: een internetverbinding en root-rechten (sudo).", o: "Software: package manager", wit: true },
  { v: "apt-commando's (8)", a: "Telkens met apt-get of apt:", o: "Software: package manager", wit: true,
    uitleg: "Bij sudo apt-get install gnome op deze commandline-only machine wil apt de volledige GUI installeren: antwoord n. Upgraden naar een nieuwere versie van de distributie: do-release-upgrade.",
    tabel: [
      ["Commando", "Wat het doet"],
      ["sudo apt update", "de database (lijst) bijwerken"],
      ["sudo apt search pakket", "zoeken (of apt-cache search)"],
      ["sudo apt install pakket", "installeren"],
      ["sudo apt remove pakket", "verwijderen"],
      ["sudo apt upgrade", "alle software bijwerken"],
      ["sudo apt update && sudo apt upgrade", "beide in 1 regel"]
    ] },
  { v: "Wat doet een package manager?", a: "Hij houdt een database bij van alle beschikbare softwarepakketten op online servers (repositories) en vergelijkt die met een lokale database van de geïnstalleerde software. Hij zoekt zelf uit welke andere pakketten nodig zijn (dependencies) en installeert of verwijdert die mee.", o: "Software: package manager",
    uitleg: "Zo kan je met 1 commando al je software, inclusief het besturingssysteem zelf, updaten. Andere besturingssystemen proberen dat na te doen met 'stores' of tools zoals Chocolatey." },
  { v: "Wat zijn repositories en dependencies?", a: "Repositories: online servers met softwarepakketten. Dependencies: andere pakketten die nodig zijn om een programma te laten werken.", o: "Software: package manager",
    uitleg: "Installeer je bv. gnome (een grafische omgeving), dan wil apt honderden extra pakketten mee installeren (de hele GUI)." },
  { v: "Welk commando gebruik je om software te beheren op Debian-distributies (en afgeleiden), en wat heb je nodig?", a: "apt-get, of apt (met een voortgangsbalk). Je hebt een internetverbinding en root-rechten (sudo) nodig.", o: "Software: package manager",
    uitleg: "Niet elke gebruiker mag zomaar software installeren." },
  { v: "Geef het commando voor:\na) de lijst van beschikbare software bijwerken\nb) een pakket zoeken (kodi)\nc) htop installeren\nd) htop verwijderen\ne) alle software bijwerken", a: "$ sudo apt update\n$ sudo apt search kodi\n$ sudo apt install htop\n$ sudo apt remove htop\n$ sudo apt upgrade", o: "Software: package manager", oefening: true,
    uitleg: "In de volgorde a) tot e). Telkens kan ook apt-get (apt-cache search voor het zoeken). Begin altijd met update: dat werkt de database bij, nog zonder iets te installeren." },
  { v: "Wat is het verschil tussen apt update en apt upgrade?", a: "update werkt de lijst (database) van beschikbare software bij. upgrade installeert effectief de nieuwere versies van alle geïnstalleerde software.", o: "Software: package manager",
    uitleg: "Vaak samen in 1 regel: sudo apt update && sudo apt upgrade (&& = voer het tweede uit als het eerste gelukt is)." },
  { v: "Hoe upgrade je je Linux-distributie naar een nieuwere versie (bv. Ubuntu 18.04 naar 20.04)?", a: "$ do-release-upgrade", o: "Software: package manager", oefening: true,
    uitleg: "Dat is iets anders dan apt upgrade, dat enkel de software binnen dezelfde versie bijwerkt." },
  { v: "Waarom moet je bij sudo apt-get install gnome op het einde n antwoorden?", a: "gnome is een grafische gebruikersomgeving: apt zou de volledige GUI met heel veel pakketten installeren, en de VM heeft daar de hardware niet voor. We willen geen GUI op deze machine.", o: "Software: package manager",
    uitleg: "Dit toont hoe apt automatisch alle dependencies wil meenemen. Extra: -y beantwoordt automatisch met ja, -s simuleert enkel." },
  { v: "Wat is het voordeel van htop tegenover top?", a: "htop is duidelijk overzichtelijker, en je kan er makkelijk een proces in killen.", o: "Software: package manager",
    uitleg: "In de oefening verwijder je eerst htop (sudo apt remove htop), merk je dat htop niet meer werkt, en installeer je het opnieuw (sudo apt install htop)." },
  { v: "Werk de lijst met beschikbare software bij.", a: "$ sudo apt-get update", o: "Software: package manager", oefening: true,
    uitleg: "Of: sudo apt update." },
  { v: "Zoek naar het pakket kodi.", a: "$ sudo apt-cache search kodi", o: "Software: package manager", oefening: true,
    uitleg: "Of: sudo apt search kodi." },
  { v: "Start htop.", a: "$ htop", o: "Software: package manager", oefening: true },
  { v: "top en htop vergelijken: voordeel htop?", a: "overzichtelijker + makkelijk een kill uitvoeren", o: "Software: package manager" },
  { v: "Probeer gnome te installeren, maar bevestig niet.", a: "$ sudo apt-get install gnome\n  n", o: "Software: package manager", oefening: true },
  { v: "Wat wordt gebruikt om software te beheren?", a: "Een package manager.", o: "Software: package manager",
    uitleg: "Package = softwarepakket." },
  { v: "Wat is volgens de cursus een van de sterkste kanten van Linux?", a: "De manier waarop software wordt beheerd: met een package manager. Dat maakt het beheren van software een stuk eenvoudiger.", o: "Software: package manager",
    uitleg: "Eén commando installeert een programma met alles wat het nodig heeft, en één commando houdt alle software (inclusief het OS) up-to-date." },
  { v: "Wat maakt dit mogelijk voor updates?", a: "Het beheren van al je software, inclusief je operating system zelf, met 1 commando.", o: "Software: package manager",
    uitleg: "Ook de kernel wordt zo bijgewerkt." },
  { v: "Wat wordt gezegd over andere operating systems?", a: "Ze zijn hier nog een eind van verwijderd, al proberen ze een vergelijkbaar systeem met hun 'store's' of tools zoals Chocolatey erdoor te krijgen.", o: "Software: package manager",
    uitleg: "Bv. de Microsoft Store of Chocolatey (een package manager voor Windows)." },
  { v: "Wat is er vereist omdat apt-get software automatisch downloadt?", a: "Een internetverbinding.", o: "Software: package manager",
    uitleg: "apt downloadt de software uit de repositories." },
  { v: "Wat is er nog vereist, en waarom?", a: "Root-rechten, want niet elke gebruiker mag zomaar software beheren. Of m.a.w., gebruik sudo.", o: "Software: package manager",
    uitleg: "Software installeren verandert het hele systeem: daarvoor zijn administratorrechten nodig." },
  { v: "Probeer het programma htop door het commando ‘htop’ in te geven.", a: "$ htop\n  htop: command not found", o: "Software: package manager", oefening: true,
    uitleg: "Dit gaat niet werken, want de software is niet geïnstalleerd." },
  { v: "Vergelijk de functionaliteit van top met htop door beide programma’s eens naast elkaar uit te voeren.", a: "Zelf uit te voeren. De tekst zegt: htop is duidelijk een stuk overzichtelijker, en biedt als extra voordeel dat je er dadelijk ook makkelijk een kill in kan uitvoeren.", o: "Software: package manager",
    uitleg: "In htop selecteer je een proces met de pijltjes en druk je F9 om het te killen. Afsluiten met q of F10." },
  { v: "Wat is erg sterk aan deze manier van werken?", a: "Apt-get zal dadelijk ook alle dependencies voor een bepaalde applicatie proberen in te vullen.", o: "Software: package manager",
    uitleg: "Dependencies = afhankelijkheden." },
  { v: "Wat gebeurt er als je gnome wil installeren op deze commandline-only versie?", a: "Gnome is een user environment voor de gui. Apt-get zal alle mogelijke pakketten die daarvoor nodig zijn automatisch mee willen installeren. Daarvoor is in dit geval ook de volledige GUI nodig, dus héél erg veel pakketten.", o: "Software: package manager",
    uitleg: "Gnome is een grafische desktopomgeving (user environment voor de GUI). GUI = Graphical User Interface." },
  { v: "Probeer eens onderstaand commando ZONDER y in te geven op het eind. We willen absoluut geen GUI op deze linuxmachine want deze ontbreekt daarvoor de nodige hardware.\nsudo apt-get install gnome (en op het eind dus n ingeven!)", a: "$ sudo apt-get install gnome\n  n", o: "Software: package manager", oefening: true,
    uitleg: "apt toont hoeveel pakketten en MB er geïnstalleerd zouden worden. Typ n, niet y: we willen geen GUI op deze machine, want die ontbreekt de nodige hardware." },
  { v: "Hoe combineer je update en upgrade in 1 commando?", a: "$ sudo apt update && sudo apt upgrade", o: "Software: package manager", oefening: true,
    uitleg: "Of: sudo apt-get update && sudo apt-get upgrade. && = voer het tweede commando enkel uit als het eerste gelukt is." },
  { v: "Hoe noem je de online servers met softwarepakketten?", a: "Repositories", o: "Software: package manager" },
  { v: "Hoe proberen andere besturingssystemen iets vergelijkbaars te doen?", a: "Met 'stores' of tools zoals Chocolatey.", o: "Software: package manager" },
  { v: "Wat is het meest gebruikte commando voor software in Debian-distro's? Wat is het verschil met apt?", a: "apt-get · apt toont daarnaast een progressiebalk.", o: "Software: package manager" },
  { v: "Waarmee begin je best altijd voor je software beheert?", a: "Met het updaten van de database: sudo apt-get update.", o: "Software: package manager" },
  { v: "Wat is kodi?", a: "Een htpc-applicatie (home theater pc).", o: "Software: package manager" },
  { v: "Met welk commando installeer je een pakket? En verwijder je het?", a: "$ sudo apt-get install pakket\n$ sudo apt-get remove pakket", o: "Software: package manager", oefening: true,
    uitleg: "Of: sudo apt install / sudo apt remove." },
  { v: "Probeer gnome te installeren maar bevestig NIET. Wat zie je en waarom weiger je?", a: "$ sudo apt-get install gnome\n  n", o: "Software: package manager", oefening: true,
    uitleg: "apt wil zeer veel dependencies installeren (een volledige GUI), en de machine heeft daar de hardware niet voor." },
  { v: "Verwijder htop, probeer het te starten en installeer het opnieuw.", a: "$ sudo apt remove htop\n$ htop\n  htop: command not found\n$ sudo apt install htop", o: "Software: package manager", oefening: true },
  { v: "Wat is een package manager?", a: "Een tool die een database bijhoudt van softwarepakketten op online servers (repositories) en die vergelijkt met de lokale geïnstalleerde software; installeert, verwijdert en updatet software.", o: "Software: package manager", examen: true,
    uitleg: "Een package manager:\nhoudt een lijst bij van alle beschikbare pakketten in de repositories\nvergelijkt die met wat geïnstalleerd is\ninstalleert, verwijdert en updatet software\ninstalleert automatisch de nodige dependencies\nVoorbeelden: apt (Debian, Ubuntu), dnf (Red Hat), winget en Chocolatey (Windows)." },
  { v: "Wat zijn repositories?", a: "Online servers met beschikbare softwarepakketten.", o: "Software: package manager", examen: true,
    uitleg: "Een repository is een server met softwarepakketten voor een bepaalde distributie en versie. Welke repositories gebruikt worden, staat in /etc/apt/sources.list en /etc/apt/sources.list.d/.\nsudo apt update haalt de nieuwste lijst van die servers." },
  { v: "Wat zijn dependencies?", a: "Pakketten die nodig zijn voor een installatie; de package manager installeert ze automatisch mee.", o: "Software: package manager", examen: true,
    uitleg: "Veel programma's hebben andere pakketten (libraries) nodig om te werken: dat zijn dependencies.\nBij sudo apt install installeert apt die automatisch mee. Voor de installatie toont apt de lijst en vraagt het om te bevestigen." },
  { v: "Welk commando beheert software in Debian-distributies? En de variant met progressiebalk?", a: "apt-get; apt.", o: "Software: package manager", examen: true,
    uitleg: "apt-get is het oudere, klassieke commando: geschikt voor scripts.\napt is de nieuwere, gebruiksvriendelijkere versie met een progressiebalk en kleuren.\nDe subcommando's zijn grotendeels hetzelfde: install, remove, update, upgrade." },
  { v: "Welke twee zaken heb je nodig om apt-get te gebruiken?", a: "Een internetverbinding en root-rechten (sudo).", o: "Software: package manager", examen: true,
    uitleg: "Een internetverbinding: apt haalt de pakketten van de online repositories.\nRoot-rechten: software installeren heeft impact op het hele systeem, dus sudo." },
  { v: "Met welke variant sync je de online repositories met je lokale database? Je hebt sudo-rechten maar bent niet root.\n\n1: sudo apt-get upgrade\n2: sudo apt-get distupgrade\n3: sudo apt-get update\n4: apt-get upgrade\n5: apt-get distupgrade\n6: apt-get update\n7: choco upgrade all -y\n8: sudo choco upgrade all -y", a: "3: sudo apt-get update", o: "Software: package manager", examen: true,
    uitleg: "update haalt de nieuwste lijst van beschikbare pakketten op en vernieuwt de lokale database: synchroniseren.\nupgrade (1 en 4) installeert de nieuwe versies; dat is iets anders.\nZonder sudo (4, 5, 6) word je geweigerd, want je bent niet root.\nchoco (7 en 8) is Chocolatey, een package manager voor Windows." },
  { v: "Waarom is \"apt-get update\" (zonder sudo) fout als je niet root bent?", a: "Je hebt root-rechten nodig; zonder sudo wordt het geweigerd.", o: "Software: package manager", examen: true,
    uitleg: "apt-get update schrijft in de lokale database in /var/lib/apt. Dat mag enkel root.\nZonder sudo krijg je een foutmelding zoals Permission denied of are you root?" },
  { v: "Waarom is choco geen correct antwoord bij Linux?", a: "Chocolatey is een package manager voor Windows.", o: "Software: package manager", examen: true,
    uitleg: "Chocolatey (choco) is een package manager voor Windows. In Linux gebruik je de package manager van de distributie, bij Debian en Ubuntu apt of apt-get.\nIn Windows is er ook winget, de package manager van Microsoft zelf." },
  { v: "Zoek naar pakketten over kodi.", a: "sudo apt-cache search kodi (of sudo apt search kodi)", o: "Software: package manager", examen: true,
    uitleg: "apt-cache search kodi zoekt in de lokale database naar pakketten waarvan de naam of de beschrijving kodi bevat. apt search kodi doet hetzelfde met een mooiere weergave.\nZoeken werkt eigenlijk ook zonder sudo; met sudo is het ook correct." },
  { v: "Installeer htop.", a: "sudo apt-get install htop (of sudo apt install htop)", o: "Software: package manager", examen: true,
    uitleg: "install gevolgd door de naam van het pakket. apt toont eerst welke pakketten (dependencies) mee geïnstalleerd worden en vraagt om te bevestigen met Y.\nMet -y bevestig je automatisch: sudo apt install -y htop." },
  { v: "Verwijder htop.", a: "sudo apt-get remove htop (of sudo apt remove htop)", o: "Software: package manager", examen: true,
    uitleg: "remove verwijdert het programma, maar laat de configuratiebestanden staan.\npurge verwijdert ook de configuratiebestanden: sudo apt purge htop.\nsudo apt autoremove verwijdert dependencies die niet meer nodig zijn." },
  { v: "Update alle geïnstalleerde software naar de laatste versie.", a: "sudo apt-get upgrade (of sudo apt upgrade)", o: "Software: package manager", examen: true,
    uitleg: "upgrade installeert de nieuwste versie van alle geïnstalleerde pakketten, volgens de lokale database.\nDoe eerst update, anders weet apt niet dat er nieuwere versies zijn." },
  { v: "Update in één commando eerst de lijst en daarna alle software.", a: "sudo apt-get update && sudo apt-get upgrade", o: "Software: package manager", examen: true,
    uitleg: "&& voert het tweede commando enkel uit als het eerste gelukt is. Lukt update niet (bv. geen internet), dan wordt upgrade niet gestart.\nMet apt: sudo apt update && sudo apt upgrade" },
  { v: "Wat is het verschil tussen update en upgrade?", a: "update vernieuwt de lijst (database) van beschikbare software; upgrade installeert de nieuwere versies.", o: "Software: package manager", examen: true,
    uitleg: "update: vernieuwt de lijst van beschikbare pakketten en versies. Er wordt nog niets geïnstalleerd.\nupgrade: installeert de nieuwere versies van de geïnstalleerde pakketten.\nVolgorde: eerst update, dan upgrade." },
  { v: "Upgrade de distributie naar een nieuwere versie (bv. Ubuntu 18.04 naar 20.04).", a: "do-release-upgrade (met sudo)", o: "Software: package manager", examen: true,
    uitleg: "do-release-upgrade upgradet Ubuntu naar een nieuwere versie (release), bv. van 18.04 naar 20.04. Met sudo: sudo do-release-upgrade.\nDat is iets anders dan apt upgrade, dat enkel de pakketten binnen dezelfde versie bijwerkt." },
  { v: "Wat gebeurt er bij sudo apt-get install gnome op een CLI-machine en wat antwoord je?", a: "Hij wil de volledige GUI met heel veel pakketten installeren (dependencies); antwoord n.", o: "Software: package manager", examen: true,
    uitleg: "gnome is een volledige grafische desktopomgeving. Op een CLI-server wil apt honderden pakketten installeren (alle dependencies): een grafische server, vensterbeheer, programma's.\napt toont hoeveel ruimte dat kost en vraagt Do you want to continue? Met n annuleer je." },
];

